quests[26864] = { id = 26864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bearer of Gnoll-edge", description = "I need you to take this back to Mountaineer Kadrell. Show it to him and tell him the nasty critters around here might be having some kind of get-together.", sourceObjective = "Deliver Foreman Sharpsneer's Head to Mountaineer Kadrell.", progress = "Any news from Algaz Station?", completion = "Gnolls and kobolds, and troggs? Oh my.\n\nI'd laugh if I didn't have another twist in the story for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[26865] = { id = 26865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Below", description = "There are enemies of the Horde beneath this very city, {class}.\n\nThe Searing Blade plots to take Orgrimmar for their own, and have already taken Ragefire Chasm! We need to storm their forces and retake what is ours!\n\nGo speak with Stone Guard Kurjack just inside Ragefire Chasm. He will have further orders for you.", sourceObjective = "Speak with Stone Guard Kurjack.", completion = "I've been expecting your arrival, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26866] = { id = 26866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Below", description = "Orgrimmar's Ragefire Chasm has been taken by the Searing Blade. {name}, we cannot allow this to pass unpunished, lest they next set their sights on Thunder Bluff.\n\nGo speak with Stone Guard Kurjack just inside the Chasm. Help him in any way you can, for our fates are intertwined.", sourceObjective = "Speak with Stone Guard Kurjack.", completion = "I've been expecting your arrival, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26867] = { id = 26867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Below", description = "With all his usual grace, Warchief Garrosh has kindly requested your presence in Ragefire Chasm to help retake it from the Searing Blade. Apparently, his reinforced city isn't as impenetrable as he thought.\n\nGo speak with Stone Guard Kurjack just inside Ragefire, I'm sure he'll be glad to have competent help.", sourceObjective = "Speak with Stone Guard Kurjack.", completion = "I've been expecting your arrival, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26868] = { id = 26868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Axis of Awful", description = "Alright, now just shut yer gob and lemme talk, 'cause here's the plan.\n\nThose gnolls and murlocs are liable to be meetin' out there somewhere. So you take this clever plant disguise of mine, and you wear it and look like a plant. Then you sneak up on 'em, and you throw this scent pheromone you gathered on the mosshide standin' with the murlocs.\n\nThen the murlocs'll flip their spit, and the mosshides will think twice about trying to work with such crazy lil' buggers!", sourceObjective = "Use the Clever Plant Disguise Kit to sneak up on the Mosshide Representative and use the Potent Murloc Pheromones on him.", progress = "Well don't just stand around here like some kinda idiot! Get out there and act like a plant!", completion = "Worked like a charm, didn't it? Maybe Kadrell will get off my darn back now what with savin' the whole town and all!\n\nI suppose you've done earned yourself some proper goods.", sourceObjectiveStatus = "unverified-source-field" }
quests[26869] = { id = 26869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Depth of the Depths", description = "<The ground trembles slightly, and the low, familiar voice of Diamant speaks as if from the stone itself.>\n\nWell done, {race}.\n\nWithin the tunnels below, you will find the stone which you seek. Painite.\n\nThe dangers ahead are many...\n\nDangers that the Stone Lords themselves fear.\n\nRemain steady.\n\nRemain strong.\n\nThe strength of the rock itself is beneath your feet.", sourceObjective = "Find the Painite within the Crumbling Depths.", completion = "<This is it. This is the stone Diamant sent you for.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26870] = { id = 26870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing the Caverns", description = "Naralex had a noble goal.\n\nOur great leader aspired to enter the Emerald Dream and help regrow these harsh lands back into the lush forest it once was.\n\nBut something went terribly wrong.\n\nNaralex's trusted allies, the Druids of the Fang, turned on him! They seek not to heal the Barrens, but to dominate it.\n\n{name}, before we can awaken Naralex and restore balance to this vital place, you need to eradicate the Fanglords. Their influence has sunk too deeply.", sourceObjective = "Ebru in the Wailing Caverns wants you to kill the Fanglords Cobrahn, Anacondra, Pythas, and Serpentis.", progress = "Are the Fanglords dead? Muyoh cannot awaken Naralex until they are!", completion = "I can already feel the balance returning! Quick, talk to Muyoh to help him awaken Naralex!", sourceObjectiveStatus = "unverified-source-field" }
quests[26871] = { id = 26871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rock Amongst Many", description = "<The ground trembles slightly, and the low, familiar voice of Diamant speaks as if from the stone itself.>\n\nYou've done as I've asked.\n\nTurn back and escape the cave in one piece.\n\nDon't forget the gemstone.", sourceObjective = "Return to Diamant at Lorthuna's Gate with the Painite Chunk.", progress = "You're alive. This is good.\n\nIs the gemstone with you?", completion = "Well done, fleshling!\n\nThe gyreworms are among our most dangerous enemies.\n\nThe other Stone Lords shall have trouble not turning their head to this accomplishment.", sourceObjectiveStatus = "unverified-source-field" }
quests[26872] = { id = 26872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deviate Hides", description = "As Naralex descended deeper into his nightmare, a strange breed of beasts arose from beneath the Barrens into the Wailing Caverns.\n\nThese deviate creatures have strange, otherworldly properties. Their very existence causes great pain to the earth. I believe that slaying them will greatly aid our work in healing the caverns.\n\nIf you feel up to the task, slay as many as you can and bring me their hides as proof of their demise.", sourceObjective = "Nalpak wants 10 Deviate Hides.", progress = "How many of the beasts have you slain?", completion = "Your efforts shall not go unnoticed, {name}.\n\nThank you for your dedication.", sourceObjectiveStatus = "unverified-source-field" }
quests[26873] = { id = 26873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preemptive Methods", description = "There is an herb in these caverns that holds untold power, {name}. Perhaps you wish to help me collect it?\n\nIt is a rare flower called Serpentbloom. I believe that in greater quantities it has the potential to prevent nightmares like Naralex's from ever occuring.\n\nUnfortunately, Serpentbloom can only be found in the darkest recesses of this place.", sourceObjective = "Nalpak wants you to collect 5 Serpentbloom.", progress = "I am eager to see if you can gather enough Serpentbloom.", completion = "You have done well, {name}. Hopefully we can use these to prevent further nightmares.", sourceObjectiveStatus = "unverified-source-field" }
quests[26874] = { id = 26874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awakening Naralex", description = "Now that the Fanglords are dead, speak with Muyoh. He will help you awaken Naralex and end this nightmare.", sourceObjective = "Speak with Muyoh.", sourceObjectiveStatus = "unverified-source-field" }
quests[26875] = { id = 26875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undying Twilight", description = "The Twilight Cultists are here! They're trying to stop the ritual! Get to the back chambers and help fight them off!", sourceObjective = "Kill 12 Twilight invaders and 1 Desecrated Earthrager.", progress = "We cannot let the binding be interrupted. They need your help in the back rooms - please hurry.", completion = "The Twilight forces continue to stream in, but it looks like the Earthen Ring defenders can handle them.", sourceObjectiveStatus = "unverified-source-field" }
quests[26876] = { id = 26876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The World Pillar Fragment", description = "It is time, {name}.  We have spotted Abyssion making his way to the lair.\n\nThe Twilight's Hammer might've thought the fragment would be safe if a dragon guarded it, but I've met enough dragons to know their one weakness.  Pride.\n\nAbyssion's not going to run from a fight with us puny mortals.\n\nPlace the banner of the Earthen Ring in the middle of his lair.  Once we defeat him, bring the fragment to Maruut.  We need to to repair the World Pillar as soon as possible.", sourceObjective = "Place the Earthen Ring Banner in the center of Abyssion's Lair, slay him and obtain the Upper World Pillar Fragment.", progress = "{name}!  You've returned!", completion = "Your efforts in repairing the World Pillar are invaluable, {name}.  Once the Temple of Earth's structure is stable again, the rift between the worlds will begin to stabilize.", sourceObjectiveStatus = "unverified-source-field" }
quests[26878] = { id = 26878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disciples of Naralex", description = "{class}, the Barrens used to be one of the most beautiful places in all of Kalimdor. It teemed with life and promise.\n\nNow, as you can see, that is no longer true. It is a land of great torment and strife.\n\nThe Disciples of Naralex seek to cleanse the Wailing Caverns and bring them back to their former beauty. Speak with Nalpak just inside the Wailing Caverns to help.", sourceObjective = "Speak with Nalpak in the Wailing Caverns.", completion = "Yes, {class}? What brings you to this place?", sourceObjectiveStatus = "unverified-source-field" }
quests[26881] = { id = 26881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Thaelrid", description = "There's something sinister going on within this place, {name}. We fear that the rumors of the Naga working with the Twilight's Hammer are true.\n\nI sent Thaelrid, one of our best scouts, further in to investigate the matter, but he hasn't returned.\n\nSeek him out. If he's still alive, find out all that he's learned.", sourceObjective = "Seek out Scout Thaelrid.", completion = "Ashelan was good to send you. There is indeed a wicked plot underway in this corrupted place.", sourceObjectiveStatus = "unverified-source-field" }
quests[26882] = { id = 26882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfathom Villainy", description = "My strength has left me. I need your help!\n\nLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from below and tainted the sacred moonwell.\n\nAku'Mai, a servant of the Old God, rose from the waters.\n\nThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.\n\nSlay Kelris and bring his head to Ashelan.", sourceObjective = "Get the head of Twilight Lord Kelris.", progress = "It is good to see you again, {name}. What news do you bring?\n\nWas your foray successful? Did you find Thaelrid?", completion = "Kelris has eluded us for quite some time.\n\nIt seems as though whenever evil made its presence known in these parts, Kelris had played a role. For some time we considered him either dead or missing.\n\nBut this makes perfect sense. By ending his reign you have spared the lives of many innocent people.\n\nTo sacrifice someone to a servant of an Old God for one's personal gain is beyond reproachful!\n\nYou have done a great deed, {name}. I thank you on behalf of Ashenvale.\n\nIf only Thaelrid had survived....", sourceObjectiveStatus = "unverified-source-field" }
quests[26883] = { id = 26883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Falls", description = "Empowered by the ancient rites of the chaotic Old Gods, the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world.\n\nWe believe that the Twilight's Hammer has allied with the naga and are amassing here.\n\nWhatever evil plan brews in the depths of the old temple must be thwarted.\n\nWage war on the Hammer and bring back proof of your deeds. Your efforts will be rewarded handsomely.", sourceObjective = "Obtain 3 Twilight Pendants.", progress = "Blackfathom Deeps was once an ancient night elf temple. It once housed a most powerful moonwell. Who knows what evil brews there now at the hands of the Twilight's Hammer.\n\nHave you made any progress in ridding the temple of their presence?", completion = "You are no doubt of brave and noble blood, {name}. We and all of the people of Ashenvale commend you for your efforts against evil.", sourceObjectiveStatus = "unverified-source-field" }
quests[26884] = { id = 26884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Researching the Corruption", description = "Foolish blood elves toil with demonic magic. Have they not witnessed what happened with the naga and with the satyrs of Kalimdor?\n\nI fear that the blood elves will meet a similar deformation. Azeroth cannot afford to give birth to another vile race of monsters.\n\nI wish to study the brain stems of the satyr and naga so that I might deduce what fate the sin'dorei are headed toward. Try to avoid harming the stems while you kill them, I won't take anything but perfect specimens.", sourceObjective = "Gather 8 Corrupt Brain Stems.", progress = "Once I have enough samples to study, my true work can begin. With the corrupted brain stems of both the satyr and naga of Blackfathom Deeps I can try to draw a correlation between the mutations.\n\nPerhaps with that gained knowledge we can prevent the blood elves from delving deeper into deformity and evil.", completion = "You have undoubtedly faced great peril to obtain these.\n\nYour actions have been selfless. It is for the good of all Azeroth that you help me with my research. I thank you, {name}, for all that you have done.\n\nNow if you'll excuse me I have much work to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[26885] = { id = 26885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowledge in the Deeps", description = "It is my duty as a trainee to collect lore for my superiors. Old lore. Powerful lore. Lore that opens doorways, and lore that could awaken more of Those Who Sleep if it is mishandled.\n\nThere are rumors of an old piece of lore, the Lorgalis Manuscript, at the bottom of the Pool of Ask'ar in a Pitted Iron Chest. It is the old dwelling of our long-dead ancestors. They held great knowledge before their city fell to ruin.\n\nSearch for the manuscript, please. I'm not skilled enough to venture further!", sourceObjective = "Find the Lorgalis Manuscript.", progress = "Your task is not an easy one, my friend.\n\nBut if you get me the manuscript, {name}...then your reward will be great and we will gain a better understanding of what it is that the Twilight's Hammer and the naga are up to.", completion = "You found the manuscript! What a joyous day this is! I will study it exhaustively and learn all there is to know.\n\nI'll make full sentinel yet!\n\nYour service to us is more than you know, {name}. I hope that this gift shows you my gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[26886] = { id = 26886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going Off-Task", description = "That nasty ship on the east side of the cove keeps firing its cannons at us. It's kinda funny seeing all the goblins get hit by cannonballs, but some of my gnome friends are being hit too!\n\nIt'd be really, really nice if you could make your way past those cannons and onto the ship. There's a mean ol' taskmaster yelling at the other deckhands in there, and I'm sure if you beat him up or kill him, they'll stop shooting at us!", sourceObjective = "Kill the Southsea Taskmaster.", completion = "Wonderful! I hope you didn't get hit with too many cannonballs.", sourceObjectiveStatus = "unverified-source-field" }
quests[26887] = { id = 26887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filling Our Pockets", description = "I know we're here to make friends with the Steamwheedle goblins, but those awful Bilgewater goblins are so rude.\n\nWhy, I just saw a bunch of them pulling gold fillings out of the teeth of the Southsea musketeers and strongarms. Do they think they can just take that for themselves?\n\nObviously, the nice thing to do is kill those pirates ourselves, take their fillings, and then give some of them to the Steamwheedle as a thank-you gift! Head on down there and beat those goblins to the punch.", sourceObjective = "Collect 20 Gold Fillings from Southsea Musketeers or Southsea Strongarms.", progress = "Have you got the fillings?", completion = "More gold! We'll be sure to give some of this to Mister Noggenfogger to smoothly ensure our continued relations.\n\nAnd only a little bit of it will go back to Gnomeregan for experimental weapons development!", sourceObjectiveStatus = "unverified-source-field" }
quests[26888] = { id = 26888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightmare of the Deeps", description = "In the darkest recesses of Blackfathom, a monster spawned by the Old Gods lurks. We know it only as Aku'mai.\n\nThe Old Gods and their servants are incredibly dangerous to our world. Long ago, they ruled over Azeroth and I fear that they seek to do so again, or destroy it while trying.\n\n{name}, Aku'mai is a creature of untold nightmare. We simply cannot allow his continued existence. Destroy him.", sourceObjective = "Kill Aku'mai.", completion = "The beast is slain. I can feel his dark presence fading away forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[26889] = { id = 26889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Cheered Out", description = "Well gosh, we've cleaned up quite a bit here!\n\n<Kelsey clears her throat.>\n\nListen, {name}, I'm looking forward to finally vacating this killbox so I can get away from these goblins and drop the cheer-act. If you'd like to continue to advance the interests of Gnomeregan, and by extension the Alliance, in the area, head south to Bootlegger Outpost.\n\nTalk to Zeke Bootscuff there, and remember that any work for the Steamwheedle will help us shut the Bilgewater out of Tanaris for good.", sourceObjective = "Talk to Zeke Bootscuff at Bootlegger Outpost.", completion = "You know, I'm usually not impressed when I see a {race}, but I've heard about what you've been doin' for the Steamwheedle. You're alright, kid.", sourceObjectiveStatus = "unverified-source-field" }
quests[26890] = { id = 26890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Essence of Aku'Mai", description = "Within the beginning tunnels of Blackfathom Deeps, there are large sapphire clusters along the cave walls. We noticed that the naga started harvesting the crystals around the same time their weaponry greatly improved.\n\nThe crystals seem to have great elemental power and, if used inappropriately, could make for a powerful component for my smithing.\n\nWill you help me, {name}? Blackfathom Deeps can be found along Zoram Strand to the north of our outpost.", sourceObjective = "Collect 20 Sapphires of Aku'Mai.", progress = "How goes your search for the crystals, {name}? Do you think they'll make an item we can use to stop the naga?", completion = "Excellent! These will do nicely. Here's a reward for your hard work.", sourceObjectiveStatus = "unverified-source-field" }
quests[26891] = { id = 26891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amongst the Ruins", description = "The Twilight's Hammer has moved into the Moonshrine Ruins here.  Their presence can only serve to coerce the elements into working against us.\n\n{name}, find the Twilight agents here, then find the ruin's fathom stone; it should be somewhere underwater, probably right underneath their own noses. In it is a fathom core - a device that when properly read it will relate a history of all elemental activity.  If I have it, the Earthen Ring and I can hopefully do something to stop them!", sourceObjective = "Extract the Fathom Core.", progress = "Have you been successful in locating the fathom core?  Without it we'll have no idea what the Twilight's Hammer is exactly up to down there.", completion = "This is exactly what I need!  A fathom core is an incredible well of information that we will be able to draw much good from.  Whatever the Twilight's Hammer is up to in there - and believe me when I say it is no good - my comrades and I will now uncover.\n\nYou've done well here today; the Earthen Ring looks upon you warmly for assisting us.  You've also helped the Horde as a whole, and for that you should be proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[26892] = { id = 26892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deep in the Deeps", description = "The Naga and the Twilight's Hammer work together to undo all the progress we've made in this area. What's more, Je'neu tells me that he feels the presence of an Old God lingering far beneath us.\n\nIf they wish to witness chaos, we will give them just that.\n\n{name}, cut down their strongest warriors, and we'll see how much they enjoy it.\n\nSearch carefully, Blackfathom Deeps is full of underwater passages and side paths in the caves that may hide your targets.", sourceObjective = "Slay Ghamoo-Ra, Lady Sarevess, and Gelihast.", progress = "Tell me, {name}, are they like running in panic? They get exactly what they deserve.", completion = "I can hear their cries from here! Maybe this will show them how foolish it is to wish for the return of an Old God.", sourceObjectiveStatus = "unverified-source-field" }
quests[26893] = { id = 26893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfathom Deeps", description = "There's a task to be done that you're perfect for, {class}. We need to secure the area around Blackfathom Deeps to help with that Alliance that are threatening Zoram'gar Outpost west of here.\n\nGo to Blackfathom Deeps, north of Zoram'gar Outpost, and speak with Je'neu of the Earthen Ring. He will have plenty for you to do.", sourceObjective = "Speak with Je'neu Sancrea.", sourceObjectiveStatus = "unverified-source-field" }
quests[26894] = { id = 26894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfathom Deeps", description = "The naga mock us with their defiance. We will drive them and their allies out of this land for good.\n\nTravel north of here to Blackfathom Deeps and speak with Je'neu Sancrea. He's already made his way inside.\n\nBe wary of Zeya, by the way. She can be a bit...temperamental at times.", sourceObjective = "Speak with Je'neu Sancrea.", completion = "Did Commander Grimfang send you? I've asked him to find suitable recruits to aid me here.", sourceObjectiveStatus = "unverified-source-field" }
quests[26895] = { id = 26895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thunderdrome!", description = "Hey, friend, you interested in excitement? Adventure? Money? Violence?\n\nWell, you'd better like violence, because they just reopened the Thunderdrome in Gadgetzan. It was sad to see it unused for so long, what with the injury lawsuits, and the racketeering charges, and the copyright infringement... But it's back, and just waiting for burly, savage folk like you to enter and throw down with the foulest opponents ever!\n\nHead to Gadgetzan and talk to Dr. Dealwell to sign up. And tell your friends!", sourceObjective = "Talk to Doctor Dealwell in Gadgetzan.", completion = "Another proud {class}, lured by the promise of fame! Of wealth! Of VIOLENCE!\n\nYes, welcome, friend. Welcome... to THUNDERDROME!", sourceObjectiveStatus = "unverified-source-field" }
quests[26896] = { id = 26896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thunderdrome!", description = "Hey, friend, you interested in excitement? Adventure? Money? Violence?\n\nWell, you'd better like violence, because they just reopened the Thunderdrome in Gadgetzan. It was sad to see it unused for so long, what with the injury lawsuits, and the racketeering charges, and the copyright infringement... But it's back, and just waiting for burly, savage folk like you to enter and throw down with the foulest opponents ever!\n\nHead to Gadgetzan and talk to Dr. Dealwell to sign up. And tell your friends!", sourceObjective = "Talk to Doctor Dealwell in Gadgetzan.", completion = "Another proud {class}, lured by the promise of fame! Of wealth! Of VIOLENCE!\n\nYes, welcome, friend. Welcome... to THUNDERDROME!", sourceObjectiveStatus = "unverified-source-field" }
quests[26897] = { id = 26897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfathom Deeps", description = "Although our position is exposed, we are safe compared to our friends inside Blackfathom Deeps! They stand mere feet away from the most deadly naga forces in the area. Speak with Sentinel Aluwyn and give them the aid they desperately need!", sourceObjective = "Speak with Sentinel Aluwyn.", completion = "Thank Elune you're here! We could use all the help we can get.", sourceObjectiveStatus = "unverified-source-field" }
quests[26898] = { id = 26898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackfathom Deeps", description = "I care deeply about these forests, {class}. Things look grim here, but I would rather face the Horde alone than watch them hack and slash their way through the trees.\n\nTravel west to Blackfathom Deeps. Once you're inside, find Sentinel Aluwyn. She's a trusted friend in need of help.\n\nThe orcs in Zoram'gar Outpost threaten her position as we speak. If they take Blackfathom, they will surely cut every tree down to fuel their insanity.", sourceObjective = "Speak with Sentinel Aluwyn.", completion = "Thank Elune you're here! We could use all the help we can get.", sourceObjectiveStatus = "unverified-source-field" }
quests[26899] = { id = 26899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Enemy of My Enemy", description = "Cultists...sacrifice...power...\n\nEnemy...awaken...\n\nOld God...imprison...me...\n\nLord...Kelris...\n\nBring head...revenge...\n\nERADICATE!!!", sourceObjective = "Obtain the head of Twilight Lord Kelris.", progress = "Revenge...reward...", completion = "<The Flaming Eradicator appears to concentrate.>\n\nI spare your life for your help, {race}. Leave now...before I change my...mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[26901] = { id = 26901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going, Going, Guano!", description = "The bats native to Razorfen Kraul produce a very peculiar natural substance. Their guano's stench seems to send the Quilboar into a murderous frenzy - and this place reeks of it!\n\nI need you to find the bat cave, and bring me a suitable sample. If we can reverse the effects and produce an antidote, we may be able to save the Quilboar.", sourceObjective = "Extract 1 pile of Kraul Guano.", progress = "Ah, I see you have returned. Were you able to procure any Kraul Guano?", completion = "Well done! This is just what we need, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26903] = { id = 26903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willix the Importer", description = "At last, help has arrived!\n\nYou have no clue how long I've been held prisoner here. I can't remember the last time I saw the outside of this place.\n\nYou see, I am an entrepreneur. Always out for a copper, as they say. I caught wind that pig snouts were selling outrageously high in the market. I figured it would be an easy in, easy out kind of affair. As you can see, I was a bit wrong!\n\nAnyway, if you'd be so kind as to help me get out of here, I'll make it worth your while.", sourceObjective = "Escort Willix the Importer to the exit of Razorfen Kraul.", completion = "Thanks again, friend! I told you I'd make it worth your while.", sourceObjectiveStatus = "unverified-source-field" }
quests[26904] = { id = 26904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruption", description = "Few people, especially among our allies, truly understand the nature of the power we wield. They shun us for pursuing knowledge that they are too weak to use properly.\n\nAs you become more powerful, you will begin to discover new spells, further magnifying your power.\n\nGo, get more experience, then return once you've learned a new spell. We'll see if you have it in you to truly master the dark arts.", sourceObjective = "Reach level 3 to learn Corruption, then cast it 5 times on a Training Dummy near the entrance to Anvilmar.", completion = "As you continue to gain power, return to me and I will teach you new spells and techniques.", sourceObjectiveStatus = "unverified-source-field" }
quests[26905] = { id = 26905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agamaggan's Charge", description = "Listen closely, mortal.\n\nThe Quilboar are my children. My blood runs deep in these lands.\n\nCharlga Razorflank has steered my children into darkness, driven into insanity by the Scourge.\n\nSlay her, {name}. Slay her and open my childrens' eyes.\n\nGive the Quilboar the chance to return to their noble roots. Let them once more earn my blessing.\n\nBring me her heart!!!", sourceObjective = "Take Charlga Razorflank's heart.", progress = "<The Spirit of Agamaggan stares at you patiently.>", completion = "Take this gift. You have earned my blessing this day.", sourceObjectiveStatus = "unverified-source-field" }
quests[26906] = { id = 26906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agamaggan", description = "I sense a being of immense power within these twisted thorns, {name}. The entire area has come alive at its presence.\n\nIt must be the Spirit of Agamaggan! He was one of the first and most powerful beings to ever live - the Quilboar worship him fervently.\n\nAll the vines you see across the land are a result of his blood; of his sacrifice to save Azeroth in the War of the Ancients.\n\nIf there's any being that could steer the Quilboar towards their noble roots, it would be him.\n\nYou must seek him out.", sourceObjective = "Talk to the Spirit of Agamaggan.", completion = "<The Spirit of Agamaggan looks at you. An ancient voice echoes inside your head.>\n\nI've been waiting for you to come here.", sourceObjectiveStatus = "unverified-source-field" }
quests[26907] = { id = 26907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Them Down!", description = "Overlord Ramtusk and the Death's Head mobilize for war. It took many scouts' lives, but we have learned of the weapon they intend to use to overtake the rest of the Barrens.\n\nIt is known as Agathelos the Raging, an immense boar outfitted with heavy armor and force-fed the rage-inducing Kraul bat guano.\n\n{race}, you must stop them before they take innocent lives!", sourceObjective = "Kill Aggem Thorncurse, Death Speaker Jargba, Overlord Ramtusk, and Agathelos the Raging.", completion = "You've done well this day. Agathelos would have taken many lives in its fury.", sourceObjectiveStatus = "unverified-source-field" }
quests[26908] = { id = 26908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeling Thorny", description = "Mankrik's furor over his dead wife raises further concerns , {class}.\n\nThe quilboar in Razorfen Kraul are far more ruthless and full of hatred than Mankrik could ever imagine.\n\nYou should travel south there and speak with my old friend Auld Stonespire. He works to put an end to their rampage before the land suffers more in its already weak condition.", sourceObjective = "Speak to Auld Stonespire.", completion = "Only a veteran like you could brave the dangers lurking here.", sourceObjectiveStatus = "unverified-source-field" }
quests[26909] = { id = 26909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stone Shards", description = "Ancient stones are strewn across this land. The elements flock to them, surrounding them protectively.\n\nThese are sites of great power, and the largest is just west of Hammerfall. Not a soul trespasses, but if you go there alone, you can hear whispers from the earth itself.\n\nI have not visited there in a long while... but our grunts have told me the whispers have started again. Would you look for me? Will you see if the stones still speak?", sourceObjective = "Investigate the Shards of Myzrael.", completion = "<The shards pulse softly, and a whisper slowly echoes through your head.>\n\nHelp...", sourceObjectiveStatus = "unverified-source-field" }
quests[26910] = { id = 26910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etched Letter", description = "I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, {name}. It appears to be a letter sealed with the insignia of Ashley Blank, our local hunter trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", sourceObjective = "Read the Etched Letter and speak to Ashley Blank in Northshire Valley.", progress = "Hello, {name}. Is there something I can do for you?", completion = "So you received my note? Excellent. You've proven yourself quite capable in dealing with those orcs. As you continue to grow in power, I will teach you some new techniques.", sourceObjectiveStatus = "unverified-source-field" }
quests[26911] = { id = 26911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Myzrael's Tale", description = "As the stone goes quiet, you're left with a vague sense of unease. Something isn't right.\n\nPerhaps you should tell Zaruk of what you've done so far.", sourceObjective = "Return to Zaruk at Hammerfall in Arathi Highlands.", completion = "I know, {name}. I should not have sent you.\n\nForgive me... the whispers of the past are sometimes too strong.", sourceObjectiveStatus = "unverified-source-field" }
quests[26912] = { id = 26912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Princess Unleashed", description = "Myzrael is a deceiver. She is an ancient force sealed long ago, and must be kept that way.\n\nYou must confront her at the Shards of Myzrael where you first spoke with her.  Summon her with this scroll, and when she has been fully brought to the surface, defeat her. Then take the Eldritch Shackles from her body and place them on the Shards to keep her fully bound once more.\n\nGood luck, {name}... may my past trouble you no more.", sourceObjective = "Summon and defeat Myzrael at the Shards of Myzrael.", progress = "The Shards of Myzrael are now strangely quiet.", completion = "As the eldritch shackles are placed around the Shards, an unhuman wail is heard from far below.  The scream is followed by a roar.\n\nThe Shards of Myzrael no longer invoke feelings of warmth and security as they once did.  Now they pulse with an open menace... as if the thing beneath them holds ill will toward the surface.", sourceObjectiveStatus = "unverified-source-field" }
quests[26913] = { id = 26913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charging into Battle", description = "Now that you've had the chance to test your abilities in battle, it's time to explain one more reason why training is so important.\n\nAs you get more experience, you'll be able to do new techniques you never thought of.\n\nGo, get some experience, learn a new skill, and demonstrate it on one of the training dummies.", sourceObjective = "Reach level 3 to learn Charge, then practice using Charge on a Training Dummy south of the entrance to Northshire Abbey.", progress = "Well, did you give it a try?", completion = "You're a quick learner, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26914] = { id = 26914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruption", description = "We must take care in how we speak around the abbey and its environs, but don't let that deter you from the path of power.\n\nAs you become more powerful, you will begin to hear the fel voices, granting you their power in the dark arts.\n\nGo, get more experience and learn a new spell. Once you have, practice it on the training dummies.", sourceObjective = "Reach level 3 to learn the Corruption ability, then practice casting Corruption 5 times on a Training Dummy south of the entrance to Northshire Abbey.", progress = "Well, did you give it a try?", completion = "I see you have already mastered Corruption!", sourceObjectiveStatus = "unverified-source-field" }
quests[26915] = { id = 26915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deepest Cut", description = "By now, you know the basics of combat as rogue, but I want to teach you a new skill. As rogues, we are renowned for our ability to execute chains of combat techniques, often saving the most powerful strikes for the end.\n\nAs you get more experience, you'll learn new things - and this is one of the ones you'll learn first. Once you have, I want you to go try it on one of the training dummies south of the entrance to the abbey.", sourceObjective = "Reach level 3 to learn Eviscerate, then find a Training Dummy south of the entrance to Northshire Abbey and practice Eviscerate 3 times.", completion = "You've caught on quickly, {name}, and a quick mind will serve you well. Return to me as you grow in power and I will show you new techniques.", sourceObjectiveStatus = "unverified-source-field" }
quests[26916] = { id = 26916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastering the Arcane", description = "As a mage, you will learn a variety of spells as your understanding grows. All you need to do is get some more experience, and the secrets of the arcane will reveal themselves to you.\n\nYou'll see. Go develop your powers, and show me what you learn.", sourceObjective = "Reach level 3 to learn Frost Nova, then practice casting it 2 times on a Training Dummy south of the entrance to Northshire Abbey.", progress = "Well, did you give it a try?", completion = "Have you mastered the use of Frost Nova already? You are a quick study in the arcane arts and you have a promising future ahead. Don't forget to return to me for training as you grow in power.", sourceObjectiveStatus = "unverified-source-field" }
quests[26917] = { id = 26917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Path", description = "I've heard about your help in clearing out some of the orcs. You've shown that you can handle yourself in combat.\n\nAs you get more experience in combat, you'll start learning how to do new things. I want you to go, get some more experience, then try the new abilities you learn on one of the training dummies south of the entrance to the abbey.", sourceObjective = "Reach level 3 to learn Steady Shot, then find a Training Dummy south of the entrance to Northshire Abbey and practice using Steady Shot 5 times.", progress = "Well, did you give it a try?", completion = "I knew you would master Steady Shot quickly.", sourceObjectiveStatus = "unverified-source-field" }
quests[26918] = { id = 26918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of the Light", description = "As you continue in your journey as a Paladin, you'll become closer to the light, learning new abilities.\n\nGo, get more experience, and learn a new ability. Demonstrate it for me, and we will continue your training.", sourceObjective = "Reach level 3 to learn Seal of Command. Cast Seal of Command on yourself and then hit a Training Dummy south of the entrance to Northshire Abbey.", progress = "Well, did you give it a try?", completion = "You're a quick learner, {name}. Return to me as you grow stronger and I'll teach you more about using the Light to vanquish your enemies and strengthen your allies.", sourceObjectiveStatus = "unverified-source-field" }
quests[26919] = { id = 26919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning the Word", description = "One of your responsibilities as a priest is caring for the wounded. Another is to go out into the world and be more... proactive about defending them.\n\nAs you do so, you'll grow in power and learn all sorts of new things.\n\nWhy don't you go out, get more experience, and then return to demonstrate what you've learned?", sourceObjective = "Reach level 3 to learn Shadow Word: Pain, then use it 5 times on training dummies near Northshire Abbey.", progress = "Have you tended to the wounds of the injured?", completion = "You're a quick learner, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26920] = { id = 26920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Andorhal", description = "Hurry, {name}... there isn't time to waste.\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  Lady Sylvanas has sent one of her best death knights to lead the charge for her cause, but I'm sure he can use all the help he can get.  With Arthas dead, now is the perfect time for the Forsaken to take Andorhal.\n\nSpeak with the bat handler, Timothy Cunningham, when you are ready, and he will put you on the first flight out there.", sourceObjective = "Report to Koltira Deathweaver within Andorhal in Western Plaguelands.", completion = "It's about time you arrived, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26921] = { id = 26921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourge First... Alliance Later", description = "Darkmaster Gandling of the Cult of the Damned leads the Scourge offensive here in Andorhal.  My old counterpart, Thassarian, leads the Alliance forces.  If we're to win Andorhal, we'll have to defeat both, but we will certainly fail if we take on both at once.\n\nI know Thassarian well enough to know that he will focus on the Scourge first.  We will do the same.\n\nTake out the weaker, desiccated Scourge to reduce their numbers.  The Alliance will have to wait to taste our wrath.", sourceObjective = "Slay 15 Desiccated Scourge within Andorhal.", completion = "You may not act quickly, but at least you do not fail me.\n\nVery well.  I will have a more important task for you, {name}, when the time is right.", sourceObjectiveStatus = "unverified-source-field" }
quests[26922] = { id = 26922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Endless Flow", description = "Araj the Summoner is bolstering the Scourge defenses with simple skeletons... an army of weaklings that will overwhelm you before it overpowers you.  He has assembled animi within Andorhal's northern towers that spew these skeletons out at an alarming rate.  But I've got the solution!\n\n<Jearl passes you a handful of grenades.>\n\nTheir function is simple.  Throwing these grenades at a bone animus... or, for that matter, a mob of skeletons... will reduce them to splinters.", sourceObjective = "Use Jearl's Hand Grenades to kill 5 Stickbone Berserkers and to destroy a Scourge Bone Animus.", progress = "I know what those devices sound like when they've blown up... and I haven't heard that sound yet.  Get back out there, {name}.", completion = "These grenades are all explosives, nothing more.  Even as a member of the Royal Apothecary Society, I recognize that some problems are not solved by throwing more plague at them.", sourceObjectiveStatus = "unverified-source-field" }
quests[26923] = { id = 26923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Machines", description = "You fools will never defeat the Scourge with those abominations running around.  Koltira blathers on about reducing their numbers, but the Scourge's best weapon here in Andorhal can be found in those lumbering brutes that are throwing my deathguards around like ragdolls.\n\nI won't have it.  {name}, enter the battlefield and destroy those monsters.", sourceObjective = "Destroy 6 Opengut Behemoths in Andorhal.", completion = "With the behemoths out of the way, our victory against the Scourge is inevitable.\n\nOur current chances against the Alliance aren't quite as favorable... but that's no concern of yours.  Not yet, anyhow.", sourceObjectiveStatus = "unverified-source-field" }
quests[26924] = { id = 26924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scholomancer", description = "The Scholomance is one of the few Scourge holdouts remaining west of the Thondroril.  The headmaster of Scholomance, a cultist by the name of Darkmaster Gandling, has made an appearance on the battlefield.\n\nThis will be his final mistake.\n\nYou will find Gandling in a square near the southern end of town.  I want you to fight and weaken Gandling.  I will join you to help finish him off.", sourceObjective = "Kill Darkmaster Gandling within Andorhal.", completion = "Excellently done, {name}.  And now, with the leader of the Scourge forces eliminated from Andorhal, we bide our time.", sourceObjectiveStatus = "unverified-source-field" }
quests[26925] = { id = 26925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Araj the Summoner", description = "With the animus destroyed, the next logical step is to take out Araj himself, and to take a shard of his phylactery.  You've probably already seen him, lurking at the fountain in the center of town.\n\nTake my grenades with you.  They won't do anything to Araj, but if he decides to summon any of those skeletons, you can use them to blow them away.  Again.", sourceObjective = "Kill Araj the Summoner. You may use Jearl's Hand Grenades to destroy Stickbone Berserkers.", progress = "Araj is a formidable opponent.  Be prepared.", completion = "Araj dead... this is good.  The Royal Apothecary Society has done its part.  As have you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26926] = { id = 26926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory, For Now", description = "The Forsaken are victorious, and our forces are still strong.  Military strategy dictates that we attack the Alliance now, while they are recovering and unaware.  I have other plans, however...\n\nWe will wait.  We attack Thassarian and his troops when the time is right.  In the meantime, speak with Rhonda Molver and take a flight to the Bulwark, on the Plaguelands' western border.  High Executor Derrington will give you your next assignment.\n\nYou will hear from me when you are needed again in Andorhal.", sourceObjective = "Report to High Executor Derrington at the Bulwark in Tirisfal Glades.", completion = "Word arrived shortly before you did, {name}.  With the Scourge ejected from Andorhal, the Forsaken has cemented its foothold in Lordaeron.", sourceObjectiveStatus = "unverified-source-field" }
quests[26927] = { id = 26927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suddenly, Murlocs!", description = "So we've got troggs working for kobolds, and kobolds working for gnolls. The gnolls must've moved in from the Wetlands.\n\nHow do I know? Well, they brought friends, because what's left of the Loch is swarming with Bluegill murlocs that were never there before.\n\nPests are pests, but this coordination is worrying. I need you to talk to Cannary Caskshot. She's one of the best hunters in these parts, and she'll know how to handle murlocs, if you can pull her away from her mug long enough.", sourceObjective = "Speak with Cannary Caskshot.", completion = "Murlocs? Sure, I've hunted murlocs.\n\nAnd every single stinkin' one of them deserved what they got! You hear me?", sourceObjectiveStatus = "unverified-source-field" }
quests[26928] = { id = 26928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smells Like A Plan", description = "Murlocs workin' with gnolls? That's a laugh! Now, just killin' them won't get you anywhere. Too many of the buggers.\n\nBut I've got a plan, usin' the old noggin, see. Those murlocs, they have this smell, they get that smell on stuff, and when another murloc smells it, they go all crazy! Makes great bait for 'em.\n\nAnyway, they've got little glands that have that smell in 'em. You go and get me a bunch of those.", sourceObjective = "Collect 7 Murloc Scent Glands from any Bluegill Murloc in The Loch.", progress = "Now don't you stink all to high hell! I'm assumin' that's because of the murlocs, but it's hard to tell.", completion = "Phew! Ain't that a stench.\n\nNow you prepare yourself, because I'm about to wow you with what's left of my mental faculties.", sourceObjectiveStatus = "unverified-source-field" }
quests[26929] = { id = 26929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Load of Croc", description = "Now while you're runnin' around doin' whatever the heck it is that you do, would you mind helpin' me out a bit?\n\nSee, I usually go out huntin' crocolisks down in the loch, but given certain circumstances, I'd rather sit here right now. Mighty polite of you not to give me grief over it, thanks!\n\nSo seein' as how you're such a <gentleman/lady>, why don't you bring me back some crocolisk jaws and I'll give you some mostly-clean money in return.", sourceObjective = "Collect 6 Crocolisk Jaws.", progress = "So did you get those crocolisk things or did I make that up?", completion = "Mighty kind of you to help out an ol' fool like me. Here's your reward as promised an' all.", sourceObjectiveStatus = "unverified-source-field" }
quests[26930] = { id = 26930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "After the Crusade", description = "Our victories are quickly piling up, {name}.  The Scarlet Crusade, which has long persecuted the Forsaken, is on its last legs.  While they still hold their monastery here in Tirisfal, they no longer occupy Hearthglen, or Tyr's Hand, far to the east.\n\nAs recently as last week, there have been reports of Scarlet Crusade activity at a small camp east of Felstone Field, but I have reason to believe that they too have been eliminated.  Travel there, and verify this information for me.", sourceObjective = "Scout the Scarlet Crusade camp located east of Felstone Field in Western Plaguelands.", completion = "Burning bodies?  No survivors?  I guessed correctly.\n\nAll the better!  We're better off without the Scarlet taint upon Lordaeron.  They epitomized all the worst things about humans.", sourceObjectiveStatus = "unverified-source-field" }
quests[26931] = { id = 26931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foxes and Hounds", description = "These Alliance forces walk around the Plaguelands like they own the place.  Well, they don't!  This land rightfully belongs to the Dark Lady!\n\nAs the battle for Andorhal drew to a close, the Alliance forces occupying the Plaguelands scattered.  Several of them can be found just east of here, hunting foxes.  Prove to them that this is Forsaken territory.\n\nKill the hunters.  Kill their hunting dogs.  And kill the foxes they hunt, for good measure.", sourceObjective = "Kill 4 Alliance Fox Hunters, 4 Bullmastiffs, and 4 Whitetail Foxes in Western Plaguelands.", completion = "It's a relief to have those hunters out of the way.  We're not done killing Alliance, however...", sourceObjectiveStatus = "unverified-source-field" }
quests[26932] = { id = 26932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buzz Off", description = "When the Stonewrought Dam burst, it drained near the entire loch. Horrible ecological devastation.\n\nAnd don't you go thinking it didn't really affect us dwarves! Not only are we plumb out of fish, but there's acres of dead threshadons out there left to rot in the sun. The buzzards are after them, and they're spreading all manner of filth and disease right on the outskirts of town.\n\nI can't ask you to clean it all up, but could you deal with the buzzards? Killin' even just a few will help.", sourceObjective = "Kill 8 Loch Buzzards.", completion = "That should help prevent disease and illness from spreading into our remaining water. Many thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26933] = { id = 26933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foes Before Hoes", description = "The men who till Felstone Field are no farmers.  They're soldiers.\n\nThassarian's forces needed food, so he sent some of the Alliance north from Andorhal, to tend Felstone Field.  The battle for Andorhal may be over, but another battle looms... Forsaken versus human.  Killing those soldiers that work at Felstone will give the Dark Lady's forces a decided advantage.", sourceObjective = "Kill 9 Alliance Laborers on Felstone Field.", completion = "Ha ha!  I hope that they come back as zombies.", sourceObjectiveStatus = "unverified-source-field" }
quests[26934] = { id = 26934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Latent Disease", description = "I need plagued grass for an... an experiment, of sorts.  Those Argent Crusaders and those infernal Cenarion druids have done too good a job of healing the plaguelands, however... and I can't find proper reagents within a reasonable walking distance.\n\nSome of the local wildlife retain the plague's touch, however.  Kill a diseased black bear, then retrieve the grass that grows where its decaying body lies.  It's not optimal, but it'll do.", sourceObjective = "Kill Diseased Black Bears in Western Plaguelands, then loot 20 Plague Tangles that grow near their corpses.", progress = "Animal tissue holds onto disease so much better than plant tissue, doesn't it?", completion = "Glorious!  This is the last bit I need.\n\nActually, stick around, {name}.  Let me tell you a little bit more about our plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[26935] = { id = 26935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northridge Lumber Mill", description = "We are not the only Argent Crusaders here in the plaguelands.  Our headquarters, Hearthglen, lies to the north.  Even nearer to the north is a small lumber mill which we also control.\n\nNathaniel Dumah is my main contact at the lumber mill.  I encourage you to speak with him, should you find yourself in that part of the woods.", sourceObjective = "Report to Nathaniel Dumah at the Northridge Lumber Mill in Western Plaguelands.", completion = "Welcome to Northridge, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26936] = { id = 26936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lower the Boom", sourceObjective = "Felstone is cleared and the bombs are set.  I hope you're ready.  I recommend covering your ears.\n\n<Derrington looks down and places his finger on an ignition switch.>\n\nEVERYBODY, PREPARE FOR IGNITION!  IN 3...\n\n2....\n\n1...", sourceObjectiveStatus = "unverified-source-field" }
quests[26937] = { id = 26937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Death is Not Enough", description = "Derrington and his men don't know it, but it was I who ordered the plaguing of Felstone Field.  We need this area for practice.  If we're to win this war for Andorhal, we need to use our newest, most versatile weapon:\n\nVal'kyr.\n\nTake my enthralled val'kyr with you, {name}, and kill the simpering Alliance scum that remain on Felstone.  Once they are dead, she will bring them back to this world... as one of us.\n\nThe Forsaken shall not die out!", sourceObjective = "Kill 8 Alliance Laborers on Felstone Field so your Enthralled Val'kyr can convert them into Forsaken.", completion = "I am able to communicate with you through the Val'kyr, {name}.  You have done well.\n\nRemain on Felstone Field.  We must now teach these newly-converted Forsaken how to fight.", sourceObjectiveStatus = "unverified-source-field" }
quests[26938] = { id = 26938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combat Training", description = "A val'kyr's only purpose is to serve, and this one serves you.  I am now giving you full control over her abilities, {name}.\n\nRoaming around the farm's outskirts, you should find several of the Forsaken that you just created.  I want you to use your val'kyr to gather at least five of them.  Once you have done so, take your newly-formed band of soldiers, bring them into Felstone's barn, and kill the beast inside.  Today, they will learn what it means to fight for the Dark Lady.", sourceObjective = "Use your Enthralled Val'kyr's Call to Arms ability to mobilize 5 Forsaken Troopers on Felstone Field. Then slay the Opengut Abomination inside Felstone's barn.", completion = "When Koltira gives his word, I will bring these val'kyr into Andorhal.  We will win.  And yet another piece of Lordaeron will fall to the might of the Forsaken.", sourceObjectiveStatus = "unverified-source-field" }
quests[26939] = { id = 26939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The G-Team", description = "How did you get in here?\n\nOh, it doesn't matter. I'm Murd Doc of the G-Team. We're the best there is, and we're here to retake Gnomeregan!\n\nWhen nobody else could help him, the High Tinker found and hired us.\n\nBut we simply can't do this alone! You're an honorary G-Team Commando now, {name}.\n\nTake this parachute, jump down straight ahead into the Hall of Gears, and kill the Viscous Fallout. After you're done, report to Commando B.E Barechus by the west hallway. You two will get along great, I'm sure.", sourceObjective = "Kill the Viscous Fallout.", progress = "What're you doing out in the open like that, fool? Get down!", completion = "I hope that wasn't too much for you. The mission is far from over!", sourceObjectiveStatus = "unverified-source-field" }
quests[26940] = { id = 26940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost Nova", description = "We are the heirs to a legacy of arcane magic and your path will not be an easy one. Many still hold us responsible for the actions of our forebears, but our talents are needed.\n\nThough you must be cautious, it is important to develop your powers, as that will deepen your connection to the arcane and grant you access to new spells.\n\nGo - get more experience with your spells, and demonstrate what you learn for me.", sourceObjective = "Reach level 3 to learn Frost Nova. Look for a Training Dummy near, and practice using it twice.", completion = "I knew you would master this lesson quickly. You are a credit to the highborn and to all our kin. Remember, as you grow in power, return to me and I will instruct you further.", sourceObjectiveStatus = "unverified-source-field" }
quests[26941] = { id = 26941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The G-Team", description = "That Murd Doc is crazy, {class}. Never, ever, let you find yourself in an aircraft with that gnome.\n\nStealth usually isn't my thing, and it's certainly not going to be yours. Go down this hallway to the Launch Bay and dispose of the Electrocutioner 6000.\n\nThe Electrocutioner is in charge of the aircraft...\n\n...and I hate aircraft. I'm not getting in any sort of aircraft!\n\nUse this parachute to drop down afterwards and speak with Commando Face for your next job.", sourceObjective = "Kill the Electrocutioner 6000.", completion = "Took you long enough. Get behind the pillar with me before you blow our cover!", sourceObjectiveStatus = "unverified-source-field" }
quests[26942] = { id = 26942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The G-Team", description = "I'd keep my distance from B.E Barechus and Murd Doc, neither is terribly stable.\n\nYou are, though, so let's get you to work! Go down into this tunnel until you get to Tinkers' Court. Hopefully you'll know what to do when you meet Mekgineer Thermaplugg.\n\nOur leader, Commando Hann Ibal waits somewhere in there. He'll reward you handsomely for all your work.\n\nProbably.", sourceObjective = "Kill Mekgineer Thermaplugg.", completion = "I'd love for you to come aboard as a full G-Team Commando, but you have other adventures to pursue.\n\nI'm sure we'll meet again, and I hope you'll have considered joining by then. Here's something for your trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[26943] = { id = 26943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home Sweet Gnome", description = "I used t' have quite the home back in Ironforge. That is, I did until I was booted out to make way for the gnomes.\n\nThey couldn't stop a bunch of troggs with all them gizmos and machines! An' I have to pay for their weakness?\n\nNo, sir. No longer.\n\nGo to Gnomeregan and talk to Commando Murd Doc. Sure, he's a gnome, but his crew, S.A.F.E. I think they call 'em, are going to take Gnomeregan back.\n\nGo! I want my house back!", sourceObjective = "Speak to Murd Doc.", completion = "Never thought I'd see a {race} like you down here. Any particular reason you're risking life and limb?", sourceObjectiveStatus = "unverified-source-field" }
quests[26944] = { id = 26944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exploring Gnomeregan", description = "The gnomish capital, Gnomeregan, hasn't been under their control for some time now. I know what it feels like to lose a home.\n\nPlease, venture inside Gnomeregan and speak to Commando Murd Doc, a member of S.A.F.E. If there's anything at all that you can do to help them take their home, I urge you to do so. There are dark secrets in those halls.", sourceObjective = "Speak to Murd Doc.", completion = "Never thought I'd see a {race} like you down here. Any particular reason you're risking life and limb?", sourceObjectiveStatus = "unverified-source-field" }
quests[26945] = { id = 26945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning New Techniques", description = "As you overcome the challenges before you, you'll begin to learn new techniques.\n\nGo, get more experience, and learn a new skill. Then demonstrate it for me on one of the training dummies.", sourceObjective = "Reach level 3 to learn Charge. Look for a Training Dummy and practice using Charge.", progress = "Speed and momentum are important tools for beating your opponents. Have you been practicing your charge?", completion = "You've proven a capable student. When it is time to resume your training, return to me and I will show you other techniques.", sourceObjectiveStatus = "unverified-source-field" }
quests[26946] = { id = 26946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rogue's Advantage", description = "I'm certain that by now, you've mastered using Sinister Strike against your enemies. But, as you learn more and advance as a rogue, you'll start to figure out new techniques. One you should figure out soon is called Eviscerate. It can be a strong way to end a combination of attacks.\n\nI want you to get some more experience, figure it out, then try it on a training dummy near the southeastern edge of Aldrassil.", sourceObjective = "Reach Level 3 and Learn Eviscerate. Look for a Training Dummy southeast of Aldrassil and practice using Eviscerate 3 times.", completion = "You've learned quickly. If you are as sharp as you seem to be, you may prove to be one of my best students yet. Return to me when you are in need of further training.", sourceObjectiveStatus = "unverified-source-field" }
quests[26947] = { id = 26947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Woodsman's Training", description = "When most people think of the kaldorei, they conjure visions of druids and sentinels, but the way of the hunter is just as ancient and just as venerable.\n\nI've been observing you, and you've had quite a bit of experience handling that bow. As you gain more, you'll start to learn some new abilities.\n\nI want you to go out, get some more experience, and figure out how to do something new. Then go use it on a training dummy near the southeastern edge of Aldrassil.", sourceObjective = "Reach level 3 to learn Steady Shot. Look for a Training Dummy southeast of Aldrassil, and practice using Steady Shot 5 times.", progress = "This is a basic technique, but it will serve you well for many years to come.", completion = "You are a quick study in our ways. I look forward to continuing your training in the future. Return to me when the time is right.", sourceObjectiveStatus = "unverified-source-field" }
quests[26948] = { id = 26948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonfire", description = "Druids play an important role in our society, but all too often we are seen as passive dreamers in a world that is changing around us.\n\nThe truth is, though, we must actively practice and go out onto the world to develop our connection to nature.\n\nSo go, get some more experience. You will begin to feel your connection deepen, learning new skills. Demonstrate the first you learn for me.", sourceObjective = "Reach level 3 to learn Moonfire. Use it on a training dummy in Aldrassil.", progress = "This is just the first of many techniques you will learn. Master them all, {name}, and you will have an impressive array of skills at your command.", completion = "You have mastered the basics of the druidic ways quickly, {name}. I have no doubt that your skills will often come in handy. Return to me when you need further training.", sourceObjectiveStatus = "unverified-source-field" }
quests[26949] = { id = 26949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning the Word", description = "As you venture out into the world and develop your skills, you will begin to learn new abilities that you never knew you had within you.\n\nI'd like you to go out, get some more experience, and then show me the first new ability you learn.", sourceObjective = "Reach level 3 to learn Shadow Word: Pain, then use it 5 times on training dummies.", completion = "You take to this well. Return to me when you need further training.", sourceObjectiveStatus = "unverified-source-field" }
quests[26950] = { id = 26950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Side of the Light", description = "The Scarlet Crusade lures in anxious young warriors with their promise to eradicate the undead. What they don't see is the dark underbelly of the entire operation.\n\nInterrogator Vishas is the cruelest man I've ever had the displeasure to meet - he 'extracted' information from my mother during the initial outbreak of the plague. The merciless Bloodmage Thalnos watches over their graveyard.\n\nThe crusaders' zealous holy rage blinds them from their own darkness. Make them regret their hypocrisy.", sourceObjective = "Kill Interrogator Vishas and Bloodmage Thalnos.", completion = "What do you mean Thalnos was an undead? That's impossible. This is a holy place, the Scarlet Crusade would never allow...\n\nTake this as a reward, and get some rest. The crypts must have gotten the best of your nerves.", sourceObjectiveStatus = "unverified-source-field" }
quests[26951] = { id = 26951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleanup on Isle E.", description = "The Battle to reclaim the Echo Isles was a costly one.  But well worth it, {class}.  The great spirit, Bwonsamdi, helped our warriors defeat the foul Zalazane.  He protected our warriors with spirits from the island.  But some of those spirits fell in battle.  Help put those spirits to rest.  On the Echo Isles, you will find masks laying about gather them and bring them here.", sourceObjective = "Gather 8 Disenchanted Tiki Masks.", sourceObjectiveStatus = "unverified-source-field" }
quests[26952] = { id = 26952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Menders' Stead", description = "I don't like the looks of what the Forsaken are doing here at the Bulwark.  Bombs, cauldrons, needless bloodshed... none of these embody that which the Argent Crusade stands for.  Furthermore, I don't like the fact that they employ mercenaries like yourself.\n\nNothing against you personally, {class}.  It's just that you could be doing so much more for yourself.  If you're interested in healing the plaguelands, rather than re-plaguing them, then report to Field Agent Kaartish at the Menders' Stead to the east.", sourceObjective = "Report to Field Agent Kaartish at the Menders' Stead in Western Plaguelands.", completion = "Welcome, {class}.  As you can see, our camp is a joint expedition between Argent Crusade members and Cenarion Circle druids, but we welcome all who wish to help heal the land.", sourceObjectiveStatus = "unverified-source-field" }
quests[26953] = { id = 26953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zen'Kiki, the Druid", description = "I am Adrine Towhide, a druid of the Cenarion Circle.  You can thank us for healing this land, where once there was only death.\n\nWe accept all who choose to follow the druidic path, regardless of race, faction, or talent.  Occasionally that means we enlist a druid who needs more help than others.\n\nI'd like you to meet Zen'Kiki.  He's pretty new, and he's still learning his craft.  Would you mind taking him out with you for a while?  You can practice combat on the plagued animals that roam nearby.", sourceObjective = "Kill 20 plagued wildlife with Zen'Kiki by your side. You may kill Hulking Plaguebears, Diseased Wolves, Venom Mist Lurkers, or Plague Lurkers.\n\nReturn to the Menders' Stead if you become separated from Zen'Kiki.", completion = "It looks like Zen'Kiki is still having a little bit of trouble with his shapeshifting.", sourceObjectiveStatus = "unverified-source-field" }
quests[26954] = { id = 26954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Different Approach", description = "Among other things, Zen'Kiki needs to work on his spell accuracy.  I could see his wrath spells spiraling out of control even from here!  In fact, I used them as a marker to follow your progress through the woods.\n\nPerhaps we can use Zen'Kiki another way.  Take him up to the top of the hill just to our east.  The diseased hawks that circle above that hill must be destroyed.  Ask Zen'Kiki to shoot at these hawks.  Even if he can't hit them, he will distract them so you can finish them off.", sourceObjective = "Bring Zen'Kiki to the top of the hill east of the Menders' Stead, then use him to summon and kill 7 Diseased Hawks.", progress = "Back so soon?", completion = "Now we're getting somewhere.  How many birds did Zen'Kiki end up killing?\n\nNone?  You killed them all yourself?\n\nAlright, I suppose we'll have to find another use for him then.  I will let you know when the time is right.", sourceObjectiveStatus = "unverified-source-field" }
quests[26955] = { id = 26955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zen'Kiki and the Cultists", description = "While you've been away, I've been trying a different approach on our friend Zen'Kiki.  I believe he may have a future as a healer.  This is mainly because healing spells never miss.\n\nI hear from Field Agent Kaartish that the cultist camp to the east is where the plagued animals are coming from.  I hope you don't mind escorting Zen'Kiki over there... perhaps he can help heal some of the plagued animals within the camp.", sourceObjective = "Bring Zen'Kiki to the Malicia Outpost in Western Plaguelands, then break 4 Captive Plaguebears out of their cages and allow Zen'Kiki to heal them.", completion = "By the grace of the Earthmother, he's done it!  Thank you, {name}!\n\nI admit, I had nearly given up hope on Zen'Kiki.  It is only due to your patience and diligence that he has come into his own as a druid and member of the Cenarion Circle.  And that's without even mentioning the good you've done for nature.\n\nYou have my admiration and respect.", sourceObjectiveStatus = "unverified-source-field" }
quests[26956] = { id = 26956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Ain't Sayin' You a Gourd-Digger...", description = "{race}!  I'm glad someone's here to help me out.\n\nWe Cenarion druids have re-cultivated Dalson's Farm, immediately behind me.  The land has flourished and our crops have been successful... mostly.\n\nA few plants seem to still be infected by the plague that ran through this land.  Perhaps their roots were too deep, perhaps the seeds were weak... I cannot say.  All I can say is that I need an able {class} like you to help me remove the bad plants from the good ones.", sourceObjective = "Remove 6 Bad Corn, 4 Rotten Apples, and 3 Unhealthy-Looking Pumpkins from Dalson's Farm in Western Plaguelands.", progress = "Have you finished killing... er, removing those plants yet?", completion = "Thank you for your help, {name}.  I know that picking vegetables isn't the most heroic task imaginable, but even the humblest tasks have their rewards.", sourceObjectiveStatus = "unverified-source-field" }
quests[26957] = { id = 26957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Long Trip Home", description = "I've been many places in my life, good {class}.  I fought the battle for Ahn'Qiraj, passed through the Dark Portal into Outland, and joined the Argent Crusade to beat down Scourge in coldest Northrend.\n\nBut before it all, I was a farmer here in Lordaeron.  Now I find myself here in Hearthglen, a scant few miles from home.  It's time I paid my respects.\n\nI'm headed to the Menders' Stead before I return home.  I wouldn't mind meeting up with you again once I get there.", sourceObjective = "Reconvene with Del Gahrron at the Menders' Stead in Western Plaguelands.", completion = "It would appear that I arrived before you, {name}.\n\nField Agent Kaartish gave me the details about my old home.  It seems my battles with the Scourge aren't quite over yet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26958] = { id = 26958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your First Lesson", description = "Let's start your training right away. As you get more experience in combat, you'll start to develop new techniques.\n\nGo, get some more experience, learn something new, and demonstrate it on the dummies to the northwest.", sourceObjective = "Reach level 3 to learn Charge. Find a Training Dummy on the northwest side of the Crash Site and practice using Charge.", completion = "Keep that technique handy, {name}. I find myself using it all the time. Return when you're ready for further training.", sourceObjectiveStatus = "unverified-source-field" }
quests[26959] = { id = 26959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stripping Their Defenses", description = "We need to eliminate the Scarlet Monastery's defenses before a true invasion can begin. Venture deep into here, their library, and assassinate Houndmaster Loksey and Arcanist Doan. They maintain the powerful defenses that protect their comrades.\n\nMy own magic will ensure your actions go undetected by the rest of the monastery. Once they are dead, I can summon in additional reinforcements to aid in our attack.\n\nWe must be successful, {name}, the Dark Lady will not tolerate failure in the slightest.", sourceObjective = "Eliminate Houndmaster Loksey and Arcanist Doan.", progress = "Did you take care of Loksey and Doan? Failing me is failing the Dark Lady, {race}.", completion = "I knew I could count on you! These fools will never know what hit them.", sourceObjectiveStatus = "unverified-source-field" }
quests[26960] = { id = 26960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Son, the Prince", description = "Great burdens have been placed on my son's shoulders in his short lifetime, and I fear his responsibilities are only going to grow.\n\nHe will never learn leadership confined to the keep, but I am loath to send him forth without escort.\n\n{name}, your deeds in the wake of this cataclysm are already legendary. You would be an excellent mentor for young Prince Anduin.\n\nPlease, introduce yourself to him. There is some pressing city business that you both can attend to for me.", sourceObjective = "Introduce yourself to Prince Anduin in Stormwind Keep. Speak with King Wrynn once you are both acquainted.", progress = "How are you two getting along? Anduin is a quick study; show him the ways of a master {class}!\n\nAre the two of you ready?", completion = "Excellent, Anduin will learn a lot by shadowing you.\n\nRemember, stay within the city's borders. Keep him out of trouble. And above all else, guard him with your life.\n\n<King Wrynn turns his attention to his son.>\n\nAnduin, no adventures! Stay close to {name} and return to the keep should you see any trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[26961] = { id = 26961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Idols", description = "Recently, just before the troggs surfaced within the site, we had uncovered a large number of strange, carved idols. But we didn't have the chance to study them, for soon after their discovery the troggs chased us away from the ruins! And those idols have a strange effect on the troggs. It makes them go berserk!\n\nBring me 8 idols - I want to study them, and I want them out of trogg hands!  You can find the idols on the troggs infesting the site.", sourceObjective = "Bring 8 Carved Stone Idols to Magmar Fellhew at Ironband's Excavation.", progress = "Do you have those idols?  We must study them and report our findings to Ironforge!", completion = "You got them!  Nicely done, {name}!\n\nAnd you don't look too worse for wear, even with those berserk troggs about.  I'm going to keep my eye on you...you show some promise.", sourceObjectiveStatus = "unverified-source-field" }
quests[26962] = { id = 26962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stripping Their Offense", description = "As you can see, {name}, our first assault on the Armory did not go as planned. We had taken the nearby courtyard until the Scarlet Champion, Herod, showed up.\n\nWe must continue our assault. The Scarlet Crusade will never be allowed to train another warrior here, let alone launch an attack on the Undercity.\n\nYour task should be obvious. Down the Scarlet Champion.", sourceObjective = "Kill Herod.", completion = "Herod is slain! The Armory will fall!", sourceObjectiveStatus = "unverified-source-field" }
quests[26963] = { id = 26963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steadying Your Shot", description = "Let's start your training right away. It's going to be a struggle to survive here, and you'll play an important role in making sure our people are safe and well-supplied.\n\nAs you become more experiened, you'll begin to discover new abilities. Go ahead and go out, learn something new, and try it out. Return to me when you think you've mastered it.", sourceObjective = "Reach level 3 to learn Steady Shot. Find a Training Dummy on the northwest side of the Crash Site and practice using Steady Shot 5 times.", completion = "Keep that technique handy, {name}. I find myself using it all the time. Return when you're ready for further training.", sourceObjectiveStatus = "unverified-source-field" }
quests[26964] = { id = 26964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Silverpine Forest!", description = "All able-bodied members of the Horde are hereby ordered to report to Grand Executor Mortuus at Forsaken High Command in Silverpine Forest.\n\nNow, more than ever, your help is needed in routing the enemy infestation of the region and conquering the port of Gilneas!\n\nTo reach Forsaken High Command you must travel south through Tirisfal Glades and enter Silverpine Forest. From there, follow the road south until you reach Forsaken High Command.\n\nOnward, <brother/sister>! Destiny calls!", sourceObjective = "Report to Grand Executor Mortuus at Forsaken High Command in Silverpine Forest.", completion = "Most excellent! A new recruit has arrived. There is much to do... much to do I say.", sourceObjectiveStatus = "unverified-source-field" }
quests[26965] = { id = 26965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warchief Cometh", description = "You're just in time, {name}nub. It is {name}nub, right?\n\n<Grand Executor Mortuus looks at a sheet of paper.>\n\nYes, that's what the paperwork says: \"{name}nub.\"\n\n<Grand Executor Mortuus points to your name on the sheet of paper.>\n\nWhere was I? Oh yes, you're just in time! The Warchief should be arriving at any moment to meet with our leader and savior, the Dark Lady herself. Just stand by and be at your best behavior. I expect that when this demonstration is over we will all receive commendations!", sourceObjective = "Stand by for Warchief Garrosh Hellscream's arrival.", progress = "Stand at attention, Dhrakloknub!", completion = "Well that was unexpected. I am not one to doubt our Warchief, but...\n\nNevermind! We have work to do. I'm sure the Dark Lady and the Warchief will get this all worked out.", sourceObjectiveStatus = "unverified-source-field" }
quests[26966] = { id = 26966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Light's Power", description = "As a paladin, you're no stranger to the Light that touches all of us. But you also have the unique power to call upon the Light to help you in battle.\n\nAs you gain more experience, you'll grow even closer to the Light and be able to call upon new powers in battle.\n\nGo, grow in experience until you have learned a new power, and then demonstrate it for me.", sourceObjective = "Reach level 3 to learn Seal of Command. Apply Seal of Command, find a Training Dummy on the northwest side of the Crash Site and hit it with an attack.", completion = "You've proven yourself a quick learner, {name}. I look forward to training you again when the time is right.", sourceObjectiveStatus = "unverified-source-field" }
quests[26967] = { id = 26967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for the Scarlet Monastery", description = "Behold the might of the Forsaken! The unstoppable will of the Dark Lady flows through our bodies! \n\nThe vast majority of the crusade's remaining forces have fled. Some, however, remain defiant.\n\nYou have been instrumental in this campaign's success. Sylvanas extends the honor of slaying her last remaining enemies to you, {name}.\n\nShow no mercy.", sourceObjective = "Kill Scarlet Commander Mograine and High Inquisitor Whitemane.", progress = "Have you performed the Dark Lady's will?", completion = "Yes! The Scarlet Monastery now belongs to the Forsaken! None can escape our wrath!\n\nYou've completed your task with the precision of a true champion. Take this as a reward, courtesy of the Banshee Queen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26968] = { id = 26968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost Nova", description = "In your future as a mage, you'll want to master a wide variety of spells. To do so, you need to deepen your connection by the arcane by growing in power.\n\nGo, get more experience as a mage, and demonstrate what you learn for me.", sourceObjective = "Reach level 3 to learn Frost Nova. Find a Training Dummy on the northwest side of the Crash Site and practice using it 2 times.", progress = "Have you practiced your charge?", completion = "You've mastered the use of this new spell quickly, {name}. I only wish all of my students were as talented. Return to me when you find yourself in need of further training.", sourceObjectiveStatus = "unverified-source-field" }
quests[26969] = { id = 26969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Strike", description = "Your walk with the elemental powers will take you to many places. As you grow in power, you will begin to learn new abilities. \n\nLet us start your journey with a simple, but useful, lesson.\n\nLearn the secret of Primal Strike, and then practice your new skill using the training dummies to the northwest of the Crash Site. Return to me when you are finished.", sourceObjective = "Learn Primal Strike by reaching Level 3, and then find a Training Dummy on the northwest side of the Crash Site and practice using Primal Strike 3 times.", completion = "It is a pleasure to teach such a capable student. As long as you continue the traditons faithfully, the shamanic arts will never be lost to our people again.", sourceObjectiveStatus = "unverified-source-field" }
quests[26970] = { id = 26970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning the Word", description = "As a priest, one of your most important duties is to use the Light's power to aid the wounded.\n\nAnother is to use your power offensively, to protect them.\n\nAs you grow more experienced, you will begin to uncover new abilities that you can use in your charge. Go, gain more experience, and then demonstrate the abilities you have learned to me.", sourceObjective = "Reach level 3 to learn Shadow Word: Pain, then use it 5 times on target dummies near the crash site.", progress = "Have you seen to the wounds of the crash survivors?", completion = "You'll often find your skills in demand, {name}. Do not hesitate to return when you need more training.", sourceObjectiveStatus = "unverified-source-field" }
quests[26971] = { id = 26971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "A noise in the main chamber of the temple draws your attention. You hear a familiar laugh... Lorthuna. She's returned to interrupt the ritual - you must stop her!", sourceObjective = "Kill High Priestess Lorthuna.", progress = "Stop Lorthuna! Don't let her interrupt the ritual!", completion = "Maruut said when all dis started dat he would gladly give his life ta see our task done. He would be proud of dis success... of dis death.\n\nDa rift be closed on dis side. Deepholm should calm down a bit. It'll be takin' time for Thrall to mend da wound in Azeroth, and we'll be needin' to remain until he finishes.\n\nThank you for all ya've done. I don't tink we could have been accomplishin' dis so soon without you.", sourceObjectiveStatus = "unverified-source-field" }
quests[26972] = { id = 26972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Side of the Light", description = "I joined the Scarlet Crusade as a young paladin, eager to cleanse the world of evil. Little did I know of the dark truth to these fanatics.\n\nInterrogator Vishas and Bloodmage Thalnos oversee this graveyard. They take great pleasure in torturing new recruits endlessly to ensure that they are 'pure'. It is an affront to the light, {class}!\n\nNo longer can I be a part of this corrupt organization. You're going to have to kill them both, so that others will never endure the same pain I did.", sourceObjective = "Kill Interrogator Vishas and Bloodmage Thalnos.", progress = "I cannot help you with your task - if we are to cleanse this place then I must maintain my cover.", completion = "What do you mean Thalnos was an undead? That's impossible. The entire mission of the Scarlet Crusade is to destroy the undead! There's just no way...\n\nYou have muddied my thoughts. Please take this reward for your achievement and leave me to rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[26973] = { id = 26973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only True Path", description = "I think that the root of the crusade's corruption can be found here. Arcanist Doan watches over the library, and teaches many young recruits to wield the arcane arts.\n\nThe Light is the only true path! You must kill him, {class}, and redeem this glorious movement!\n\n<Joseph the Awakened shifts nervously.>\n\nYou'll want to dispose of Loksey as well. His hounds seem to disapprove of our noble intent.", sourceObjective = "Eliminate Houndmaster Loksey and Arcanist Doan.", completion = "Good work! I just know the Light shines favorably upon us for our work. Our cause is righteous!", sourceObjectiveStatus = "unverified-source-field" }
quests[26974] = { id = 26974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The False Champion", description = "We...we...we had to kill them! They were coming right for us!\n\nYou believe me, don't you {name}?\n\nHerod is not the true champion of the Scarlet Crusade. I am! He took what was rightfully mine!\n\nYou should kill him. He's...a menace! Trains the soldiers to kill anyone instead of just the undead!\n\nI'll reward you handsomely...", sourceObjective = "Kill Herod.", completion = "So he's really dead? That means...I, Joseph, am the new Scarlet Champion!!!\n\nTake this. I don't have a need for such possessions anyways! I'm the Scarlet Champion, after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[26975] = { id = 26975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rallying the Fleet", description = "I am amassing a warfleet to assault Twilight Highlands and bring an end to Deathwing's lackeys. My soldiers are ready but fleet preparations lag behind.\n\nMy men at the docks need some inspiration and motivation. A visit from the Prince here should lift their spirits and remind them of the bright future they're fighting for.\n\nTake Prince Anduin to the docks with you and speak with Supply Sergeant Graves. I want Anduin to observe how a natural leader handles the situation.", sourceObjective = "Escort Prince Anduin to the Stormwind Docks and talk to Supply Sergeant Graves. If you get separated from the Prince, you'll find him in the Stormwind throne room.", progress = "I was told to expect the Prince Regent. Who are you?", completion = "<Graves bows respectfully to the Prince.>\n\nPlease understand your highness, the men are working double-shifts. The scale of your father's operation is enormous.\n\nBut we will endeavor to wrap things up. I give you my word.", sourceObjectiveStatus = "unverified-source-field" }
quests[26976] = { id = 26976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for the Scarlet Monastery", description = "Oh, it's great to see you again {name}! I'm afraid I'm going to need your help.\n\nYou see, Mograine's the Commander here along with High Inquisitor Whitemane, and they tried telling me that I wasn't really the new Scarlet Champion! 'Course, the boys and I didn't take kindly to that.\n\nWe're taking the Scarlet Monastery for our own and re-establishing the order as it always should have been - with me at the head of things! I'll take care of the Forsaken and the Scourge for good.\n\nHelp an old friend out?", sourceObjective = "Kill Scarlet Commander Mograine and High Inquisitor Whitemane.", completion = "Yes! The Scarlet Monastery is ours! You're a real friend. Take this as a reward, and feel free to visit again once I've taken the Undercity too.\n\nIt'll be a Scarlet Paradise!", sourceObjectiveStatus = "unverified-source-field" }
quests[26977] = { id = 26977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Investigation", description = "The city is still reeling from the seditious acts of the Twilight's Hammer in recent months. They prey on peasant fears and corrupt our most important citizens. We need to find out how deep the conspiracy runs.\n\nI've tasked Major Samuelson of the Stormwind City Guard to head up an investigation. He's right here in the throne room. See if you can assist his efforts.", sourceObjective = "Speak with Major Samuelson in Stormwind Keep.", completion = "Hmmm, yes? My investigation of the Twilight's Hammer. Of course.\n\nYour assistance will be valuable.", sourceObjectiveStatus = "unverified-source-field" }
quests[26978] = { id = 26978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Needs Cauldrons?", description = "Have you seen the condition of Felstone Field?  The Alliance forces at Andorhal have taken the area, and they're using it to... to... to grow CROPS!\n\nI almost liked it better when the Scourge held the area.  At least they had the sense to put a giant plague cauldron in the middle of the field.\n\nWe're going to take that farm back from these humans, {name}.  Take these drums and place them at key locations around the field.  I'll be waiting here at the Bulwark.", sourceObjective = "Place Dithers' Plague Drums near the Windmill, the Grain Silos, the Ranch House, and the Barn at Felstone Field.", completion = "<Dithers practically glimmers with excitement.>\n\nThe drums are placed?  In their positions?\n\nVery well then, I will give the word to the High Executor.  When the time is ready, he will be the one to press the ignition switch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26979] = { id = 26979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange New Faces", description = "Now that Felstone is ours, we can use its acreage - and any dead bodies we find - for our own purposes.  I've received orders from higher up that you are going to be helping out in this process.\n\nYou may have met Lindsay Ravensun on the battlefield in Andorhal.  I've never met her before, but she seems to have made some friends in high places, because she's taking over operations at Felstone.  You're to meet her at the charred Scarlet camp... the one you scouted out earlier.", sourceObjective = "Report to Lindsay Ravensun at the Charred Outpost in Western Plaguelands.", completion = "{name}.  The Dark Lady watches over you.", sourceObjectiveStatus = "unverified-source-field" }
quests[26980] = { id = 26980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swiftgear Station", description = "You've done good work here, {name}. Askin' you to haul sandbags would be a waste, to be honest; I'd rather send you along where your skills are needed.\n\nWe've got a small outpost up north in the marsh. Swiftgear's the gnome that built it, but you'll want to talk to Shilah Slabchisel and help her with Ironforge matters.\n\nI'll admit, she's a looker... but I wouldn't make the mistake of getting fresh with her! They don't call their family Slabchisel for nothing.", sourceObjective = "Speak with Shilah Slabchisel at Swiftgear Station, north of Menethil Harbor.", completion = "Stoutfist sent you, eh? He's a good captain, runs his men well. Just wish he'd stop starin' at my midriff.\n\nDon't let me catch you doin' it either. We've work to take care of here!", sourceObjectiveStatus = "unverified-source-field" }
quests[26981] = { id = 26981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whelgar's Retreat", description = "Prospector Whelgar's been leading an excavation in the mountains southeast of here for quite some time. He had some raptor problems back in the day, but things were going better recently.\n\nJust the other day, we got word he had to evacuate the entire digsite again. I'm not sure what's going on there, but I can't imagine the cataclysm making a quarry any safer than it was before.\n\nThere's good dwarves working there, {name}. Would you go see what's wrong there, and maybe lend a hand?", sourceObjective = "Speak with Prospector Whelgar at Whelgar's Retreat, southeast of Swiftgear Station.", completion = "Well met, {class}. We've got raptor problems for sure... sort of.\n\nMore like the entire dig site deciding to attack us. I've never seen rocks and fossils get so upset!", sourceObjectiveStatus = "unverified-source-field" }
quests[26982] = { id = 26982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scarlet Monastery", description = "The same Monastery in Tirisfal Glades that the Scarlet Crusaders now occupy used to be a major training ground for our paladins. Now the Forsaken loom over it from the Undercity and the Crusade prevents us from utilizing it to train the very soldiers we need to deal with the Forsaken!\n\nLook, I don't trust him, but Joseph the Awakened waits inside the graveyard. Go speak with him - although he is a crusader, he says he now rebels against them, providing us with an opportunity to take back what's ours.", sourceObjective = "Visit Joseph the Awakened.", completion = "Captain Nials sent you? I haven't seen her in ages! How is she? Did she get my letter?\n\nOh, you're not here for that. Well then, let's get down to business!", sourceObjectiveStatus = "unverified-source-field" }
quests[26983] = { id = 26983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Close Enough", description = "Make no mistake - there is a ton of stuff to be done here! However, we also need to strike at the Forsaken where it hurts. The Scarlet Monastery in Tirisfal Glades is the perfect distance from the Undercity and Brill.\n\nReport to Joseph the Awakened in their Library. He's a rebel crusader that can hopefully help us take the Monastery as our base of operations in that region, and maybe take out Arcanist Doan, one of their most powerful mages, in the process.", sourceObjective = "Visit Joseph the Awakened.", completion = "You came here from Southshore, eh? I bet you hunger for revenge against the vile Forsaken that trashed the place. The Scarlet Crusade can help take care of that!\n\nRight after you help me realign their misguided souls, that is.", sourceObjectiveStatus = "unverified-source-field" }
quests[26984] = { id = 26984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Old, Crazed Friend", description = "Joseph the Crazed was one of my good friends before he joined the Scarlet Crusade up in the Scarlet Monastery in Tirisfal Glades. I heard that he's in the Armory there trying some ridiculous attempt at taking over Herod's position as Scarlet Champion.\n\nIt's a death wish to challenge Herod like that! Go up there and try to talk him out of it.", sourceObjective = "Visit Joseph the Crazed.", completion = "You look pretty tough, {class}. There are wrongs to be righted here. Let's get started.", sourceObjectiveStatus = "unverified-source-field" }
quests[26985] = { id = 26985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pitting Madness Against Madness", description = "Our renewed forces can handle the situation here for a while without you. I've received reports that Joseph the Insane, a former Scarlet Crusade officer, is in the Scarlet Monastery Cathedral and is taking his band of renegades to strike out against Scarlet Commander Mograine.\n\nThis is an excellent opportunity. Go there and help him with his insane task, and maybe we can use the Monastery as an excellent stronghold right at Sylvanas' doorstep!", sourceObjective = "Visit Joseph the Insane.", completion = "Wait, you were sent here by THE Shandris Feathermoon? I can barely believe my ears! To know that my cause is supported by her massive army...\n\nYes, yes, you will be perfect. You're the key to my future!", sourceObjectiveStatus = "unverified-source-field" }
quests[26986] = { id = 26986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Scarlet Monastery", description = "Oftentimes the best way to ensure our men sustain as few injuries as possible is to cause great harm to our enemies in their very homes and prevent battles from ever occurring!\n\nTravel to the Scarlet Monastery and speak with Dark Ranger Velonara in their graveyard. She is leading a Forsaken assault there and could benefit from a seasoned {class} such as yourself.", sourceObjective = "Report to Dark Ranger Velonara.", completion = "It looks like Darthalia sent an able {class}, as I requested.", sourceObjectiveStatus = "unverified-source-field" }
quests[26987] = { id = 26987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Right Way", description = "My people are not generally fond of the arcane arts that so many other races abuse. Thankfully the wizards within the Scarlet Monastery library are separated from us by considerable land, but their ability to transcend the physical realm concerns me and, ultimately, my tribe's survival.\n\nTravel far to the west to the monastery's library and speak with Dark Ranger Velonara there. Her forces are already poised to strike at Arcanist Doan himself, head magi for the crusade.", sourceObjective = "Speak to Dark Ranger Velonara.", completion = "I'm surprised to see Huntsman Markhor working with me for once. He's usually quite stubborn. He does tend to a strong hatred for magic, though.\n\nI hope you do, too, {class}, because we're going to strip the Scarlet Crusade of theirs.", sourceObjectiveStatus = "unverified-source-field" }
quests[26988] = { id = 26988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moving Things Along", description = "I'm waitin' on some very powerful reagents I ordered from the Undercity not long ago. I heard that the shipment is late because the Scarlet Monastery's crusaders are blocking its passage. Da Scarlet Champion, Herod, is likely to blame for dis annoyance.\n\nPlease go speak to Dark Ranger Velonara in the Scarlet Monastery's armory, she is goin' to 'take care' of Herod, which means my shipment will arrive safely!", sourceObjective = "Visit Dark Ranger Velonara.", completion = "Yayo'jin is correct, you helping me here will aid her in the Hinterlands as well.\n\nAll the more reason to get started immediately.", sourceObjectiveStatus = "unverified-source-field" }
quests[26989] = { id = 26989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gilneas Liberation Front", description = "The battle over this region still rages, {name}nub. Although we soundly beat back the Gilnean defenses and took Gilneas for the Horde, a small group of rebels managed to escape. The \"Gilneas Liberation Front\" - as they call themselves - make attacks of opportunity against our forces in the field. The rebels have had a few minor victories and now grow brazen in their assaults! The time to strike back is now, {name}nub.\n\nVenture south into the wilds of Silverpine and kill any rebel that you cross.", sourceObjective = "Kill 10 Worgen Renegades.", progress = "What have you to report, Æthelwolfnub?", completion = "Peterbonenub has returned! And in one piece!\n\nDefender of Silverpine! Redeemer of the Horde! Peterbonenub, your bravery must be rewarded!", sourceObjectiveStatus = "unverified-source-field" }
quests[26990] = { id = 26990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water They Up To?", description = "It appears that the Sandfury trolls are working with the Twilight's Hammer.\n\nNo matter. That foul witch won't be sending her monster to MY city.\n\nCome, brave ones! We'll slick the sand with their gore and return home triumphant. Tell Hamuul Runetotem what's happened here when we've gotten back; I'll need to oversee the return of the citizenry, repairs, and so on.", sourceObjective = "Slay Kai'ju Gahz'rilla and inform Hamuul Runetotem in Thunder Bluff.", sourceObjectiveStatus = "unverified-source-field" }
quests[26991] = { id = 26991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Abroad", description = "Sometimes we must acknowledge the need to protect our allies so that they may protect us. This is one such occasion, {race}.\n\nTravel to the Scarlet Monastery near the Undercity in Tirisfal Glades. Once you arrive, go to the Cathedral and speak with Dark Ranger Velonara. She is leading the final assault against the crusade there, and it would benefit us all greatly to ensure our undead allies secure the monastery before the crusaders have a chance to attack their capital.", sourceObjective = "Find Dark Ranger Velonara.", completion = "Nazeer is a strong warrior - his hatred for our enemies rivals my own. You are welcome help to my forces.", sourceObjectiveStatus = "unverified-source-field" }
quests[26992] = { id = 26992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agony Abounds", description = "You have no doubt heard about the incident that transpired at the Wrath Gate in Northrend, yes? Due to those unfortunate events we are strictly forbidden from using the strain of life-shattering blight that we finally perfected. Now we have rules and regulations and other nonsense!\n\nThey've given us some neutered version of the perfected blight and expect us to weaponize it.\n\nIf I'm to get this crap functional I'll need several bags full of ferocious doomweed. You'll find it all over Silverpine.", sourceObjective = "Gather 8 Ferocious Doomweed.", progress = "Have you collected the ferocious doomweed I requested?", completion = "Agony abounds, friend! The land itself threatens to devour us, and yet we persist. I wonder why that is? With this doomweed and the guts and gore that T'Veen needs, we might have something suitable to send to the Forsaken front.", sourceObjectiveStatus = "unverified-source-field" }
quests[26993] = { id = 26993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Compendium of the Fallen", description = "Don't fret, I serve no master, {race}. Within these halls lies a book called the Compendium of the Fallen. It holds vast amounts of research that the Scarlet Crusade has done on my kind over the years.\n\nSimply put, I'd like you to retrieve it and bring it back to me. No questions asked.", sourceObjective = "Retrieve the Compendium of the Fallen.", progress = "I don't want to stay in a monastery packed full of undead-hating zealots for much longer. Surely you can understand why. Don't speak to me if you don't have the book with you.", completion = "Well done. How about I give you a nice reward for your work, and you don't tell a soul that you saw me here. Deal?", sourceObjectiveStatus = "unverified-source-field" }
quests[26994] = { id = 26994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Without Rhyme or Reason", description = "I heard that Joseph the Crazed wants you to kill Herod. While you're at it, how about you slaughter their top soldiers? I'll pay you well for your work.\n\nDon't worry about the why, just worry about the how.", sourceObjective = "Kill 3 Scarlet Myrmidons, 3 Scarlet Protectors, 3 Scarlet Guardsmen, and 3 Scarlet Evokers.", progress = "Let's not play games. Are they dead or not?", completion = "Very good. Yes, very good indeed.\n\nYour reward, as promised. No questions.", sourceObjectiveStatus = "unverified-source-field" }
quests[26995] = { id = 26995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guts and Gore", description = "If we're to get this new blight up and running we'll need clean beast guts. The problem is that clean beast guts are a rare commodity in Silverpine Forest. Most of the beasts here have succumbed to disease and thus only have diseased organs.\n\nDo a sweep of the forested area east of here for worgs and grizzled bears. Kill only the non-diseased variety and rip out their entrails. Bring me all of the clean guts that you can stuff into your backpack!", sourceObjective = "Recover 6 \"Clean\" Beast Guts.", progress = "Remember, I can only use clean beast guts for the new strain of blight we're developing.", completion = "Excellent! With these guts and the ferocious doomweed we'll be able to test out our new strain of blight. Now to select a suitable target...", sourceObjectiveStatus = "unverified-source-field" }
quests[26996] = { id = 26996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Right Under Their Noses", description = "In the right side-room of the accursed cathedral ahead there is a torch on the wall. Move it and a secret door will open. Inside is High Inquisitor Fairbanks. He is now an undead.\n\nI need him taken care of. Kill him in his own room if possible, I'd strongly prefer the crusaders not see him. You know the deal - kill him, and I'll reward you. No other words are necessary between us.", sourceObjective = "Kill High Inquisitor Fairbanks.", progress = "<Dominic stares at you.>", completion = "<Dominic hands you your reward. No words are spoken.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26997] = { id = 26997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Usual Suspects", description = "<Samuelson scratches his chin, absently.>\n\nMy investigations reveal, ah, it's likely that there's trouble brewing among the Stormwind dock workers. Shifty lot. Don't trust 'em.\n\nYou should go there and shake the place down. Start grilling those longshoremen. That should keep you busy.\n\nGo rout out those Twilight infidels!", sourceObjective = "Grill 6 Stormwind Dock Workers in Stormwind Harbor.", progress = "Samuelson didn't seem to give you a lot of credit. Do you really think the dock workers have anything to do with the Twilight's Hammer?", completion = "This doesn't make any sense, {name}.\n\nWhy was Samuelson sending us out here on a wild goose chase?\n\nSomething doesn't feel right. We should poke around on our own...", sourceObjectiveStatus = "unverified-source-field" }
quests[26998] = { id = 26998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iterating Upon Success", description = "The concoction is finally ready, but before I can put my seal of approval on this strain, we'll need to run a field test.\n\nSpeak to Bat Handler Maggotbreath, here at High Command, and requisition a bat. The bat will take you to the Dawning Isles, east of here across Lordamere Lake, right into the heart of depravity itself - the Vile Fin murloc dens!\n\nUse the concoction against the murlocs and report the results back to me.\n\nThose results being that you killed them all, as commanded!", sourceObjective = "Kill 50 Vile Fin Murlocs.", progress = "Have you exterminated the Vile Fin murlocs of the Dawning Isles?", completion = "Potent enough to exterminate a thousand murlocs! I think I'll put that on the label. You've done well, {name}, and great work around here gets rewarded.", sourceObjectiveStatus = "unverified-source-field" }
quests[26999] = { id = 26999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Era for the Plaguelands", description = "No longer does the Scourge hold this area.  We, the living, are retaking Lordaeron.\n\nWe have taken great strides already, as you have already seen.  The earth flowers, the trees grow tall and green, and the wildlife is beginning to return.  Yet a few remnants of undeath remain.\n\nWhile the trees and grass prosper, the animals are struggling.  Something is preventing them from healing, and I intend to find out what.  Bring me samples from the plagued wildlife so that I may study them more closely.", sourceObjective = "Obtain 4 Plague Lurker Samples, 4 Venom Mist Lurker Samples, 4 Hulking Plaguebear Samples, and 4 Diseased Wolf Samples.", progress = "Once the animals are healed, our duties here will be nearly complete.", completion = "This will be more than enough, {name}.  Now, I will need some time to perform my studies.", sourceObjectiveStatus = "unverified-source-field" }
quests[27000] = { id = 27000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning the Ropes", description = "Ah, it's good to be back in Northridge!  I've got my mill, my beautiful wife, a bouncing baby boy... I've even put in my hat with the Argent Crusade.  We'll be supplying Tirion's forces with lumber.\n\nMy lumberjacks were being exceptionally productive, too... up until the point when the spiders came.  Now they refuse to go any deeper in the woods.\n\nMaybe you can help me out.  Hop on one of my horses and use it to frighten those spiders.  Maybe we can avoid bloodshed and just scare them away.", sourceObjective = "Mount a Hearthglen Mustang at Northridge Lumber Mill, then use its Whinny ability to frighten 25 Northridge Spiders.", progress = "The spiders tend to be a little skittish.  One of the mustangs should be enough to scare them away.", completion = "Well, it sounds like they're certainly afraid of the mustang, but they're not leaving for good.  I can't have you running around on a horse forever.  Nor do I think you'd want to.\n\nFine.  Bloodshed it is.", sourceObjectiveStatus = "unverified-source-field" }
quests[27001] = { id = 27001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Means WAR (Wild Arachnid Roundup)", description = "The Highlord was generous enough to send some of his recruits to protect us here at the mill.  With your horsemanship skills, and their martial prowess, we can do away with this spider problem easily.\n\nHop back on that mustang and scare those spiders again, but this time, scare them all the way up here to the mill.  These Hearthglen recruits can handle things from there.", sourceObjective = "Mount a Hearthglen Mustang near the Northridge Lumber Mill, then use its Whinny ability to send 10 Northridge Spiders to the Hearthglen Recruits at the Northridge Lumber Mill. You can round up several spiders at once.", progress = "I don't need you to kill the spiders... that's what these soldiers are for.  Think of it as killing two birds with one stone: we're getting rid of the spiders, and the recruits are getting valuable combat experience.", completion = "That's much more like it!  Now my lumberjacks can get to work again.\n\nNice riding out there, {name}.  You cut a pretty impressive silhouette on that mustang.", sourceObjectiveStatus = "unverified-source-field" }
quests[27002] = { id = 27002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Audience with the Highlord", description = "Oh, before you go, {name}... I have a message for you.  There's someone in Hearthglen who'd like to meet with you.  Said he's \"heard your name pop up\" a few times already.\n\nConsider yourself lucky, {name}.  Not everybody gets a personal audience with Highlord Tirion Fordring.\n\nOh, and feel free to use one of my mustangs for the ride up there.  They're the fastest money can buy.", sourceObjective = "Report to Highlord Tirion Fordring at Hearthglen in Western Plaguelands.", completion = "{name}.  It is truly a pleasure.\n\nI know you are young, and still training, but I've had my eye on you.  We among the Argent Crusade are always looking for promising new recruits, and you have indeed shown great promise.  I have no immediate tasks for you, but merely wished to meet you in person, and see for myself what type of {race} you really were.\n\nFor the time being, the amenities of Hearthglen are yours to enjoy.  I look forward to our next meeting, {name}.  You are dismissed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27003] = { id = 27003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easy Money", description = "Well, hello there!\n\nWhatever brought you, I'm so glad that you're here! My friends will never admit to it, but we could really use a hand.\n\nThe ancient region of Uldum has been exposed! Treasures beyond your wildest dreams, free for the taking!\n\nWe just need a bit of an escort, what with the bandits and all...\n\nYou'll accompany us, won't you?\n\nYou're welcome to all the loot you can haul off!", sourceObjective = "Accompany Adarrah's caravan into Uldum.", completion = "Smells like someone else was in this cell recently.\n\nGross!", sourceObjectiveStatus = "unverified-source-field" }
quests[27004] = { id = 27004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Plot", description = "We came here to investigate rumors of a Titan artifact up at the Masters' Gate to the southwest.\n\nOne of those Twilight's Hammer cultists must have the plans for what they're doing up there. You're going to have to get them for us, {name}.\n\nKeep searching the cultists until you find them.", sourceObjective = "Collect the Masters' Gate Plans.", progress = "Those plans are the key to everything.", completion = "<Mowi takes a look at the plans that you hand to her.>\n\nBut... but, this is just gibberish!\n\nWhat does this even say? What language is that?", sourceObjectiveStatus = "unverified-source-field" }
quests[27005] = { id = 27005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Plot", description = "We came here to investigate rumors of a Titan artifact up at the Masters' Gate to the southwest.\n\nOne of those Twilight's Hammer cultists must have the plans for what they're doing up there. You're going to have to get them for us, {name}.\n\nKill cultists at the Masters' Gate until you find them.", sourceObjective = "Collect the Masters' Gate Plans.", progress = "Those plans are the key to everything.", completion = "<The examiner takes a look at the plans that you hand to him.>\n\nThis is just gibberish!\n\nWhat does this even say? What language is that?", sourceObjectiveStatus = "unverified-source-field" }
quests[27006] = { id = 27006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fly Over", description = "I tried ta fly o'er the terrace an have a look fer myself, but those toastie eatin' pansies kept shootin' at me, an I couldn't get near.\n\nYa look like ya might be handy with the reins. Why don' ya take yer flyin' beastie up there ta the southwest and see what all the fuss is about?", sourceObjective = "Investigate the central area in the back of the Masters' Gate.", completion = "A waygate?! The culties dug up a Titan waygate?", sourceObjectiveStatus = "unverified-source-field" }
quests[27007] = { id = 27007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silvermarsh Rendezvous", description = "Excellent work, {name}.  We know exactly where the meeting location is.\n\nThe Upper Silvermarsh is a mercury swamp to the east of here.  It's normally only inhabited by elementals and occasional stone troggs, but our scouts have seen some Twilight activity in the region.\n\nMake your way there and let's find a way to eavesdrop on the Forgemaster's meeting.", sourceObjective = "Go to the Upper Silvermarsh in Deepholm.", progress = "We'll get that fragment back, {name}.  We have no choice.", completion = "This is the place.  Our scouts confirmed the presence of high-ranking Twilight officers nearby as well as potential trogg hunting parties.\n\nBe on the lookout, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27008] = { id = 27008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fly Over", description = "I'm quite adept at riding my flying carpet. Unfortunately, when I tried to investigate what the cultists had uncovered up at the Masters' Gate, they nearly shot me down.\n\nYou look as if you might be skilled with the flying reins as well. Would you mind flying up there to the southwest to see what they've unearthed?", sourceObjective = "Investigate the central area in the back of the Masters' Gate.", completion = "A waygate?! They unearthed a Titan waygate.\n\nThis is very interesting and potentially very bad.", sourceObjectiveStatus = "unverified-source-field" }
quests[27009] = { id = 27009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Coldbringer", description = "Amnennar the Coldbringer rules over the Razorfen Downs with very dark and powerful Scourge magic. I have managed to clear an opening in the thorns just above his seat of power, but his sorcery prevents me from launching an assault.\n\nIf you venture up the Spiral of Thorns and engage him, he will be distracted long enough for me to attack him briefly, weakening him before he can use his most deadly spells. Once he is weakened, destroy him without mercy.", sourceObjective = "Kill Amnennar the Coldbringer.", completion = "A job well done, {name}. The Quilboar here can no longer be saved, but at least they are no longer organized for attack, or slaves under Amnennar's tyrannic rule.\n\nLeave quickly, please. Razorfen Downs is without hope. It must be purged.", sourceObjectiveStatus = "unverified-source-field" }
quests[27010] = { id = 27010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quicksilver Submersion", description = "The troggs in Deepholm have proven to be every bit as hostile as the ones in Azeroth.  Yet perhaps their presence will prove useful to our efforts.\n\nThe crates they use for trawling through the mercury will conceal you perfectly if you submerge yourself beneath the marsh.\n\nUse it to approach the Twilight's Hammer camp in the eastern end of the Upper Silvermarsh undetected.", sourceObjective = "Obtain a Trogg Crate and use it to submerge yourself and eavesdrop on the Twilight's Hammer camp to the east.", completion = "We have the information we need.  Let's not tip our hand by engaging the enemy too soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[27011] = { id = 27011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redpine Thievery", description = "Farther to the south, you will find Redpine gnolls... a new arrival to the area.  You probably passed some on your way here.  Nathaniel pretends like they're not a problem, but I know better.\n\nI've seen them running away with our lumber at night.  I don't know what they'd do with lumber - they don't seem particularly handy - but that doesn't stop them from stealing it.  Head down to their camps and steal that lumber back.", sourceObjective = "Retrieve 10 piles of Northridge Lumber from the Redpine Camp in Western Plaguelands.", progress = "Some of the older lumberjacks tell me that the Redpine lived in the area several years ago, but left when the plague arrived.  That doesn't make it OK for them to steal, though.", completion = "I'll just put this back over in the lumber stores outside.  Nathaniel probably won't even notice it was missing.", sourceObjectiveStatus = "unverified-source-field" }
quests[27012] = { id = 27012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gnoll's Resolve", description = "I have my doubts about those gnolls' intentions.  They haven't attacked us yet, but their numbers are growing, and they seem to always have their weapons ready.  I'm no military expert, but that seems a little aggressive to me.\n\nMaybe if we took away some of their weapons, they'd be a little less likely to pose a threat to our mill.  I'd feel much better about the whole situation if you went down there and brought some of their weapons back to me.", sourceObjective = "Obtain 6 Redpine Staves and 6 Redpine Clubs from Redpine Gnolls.", progress = "I don't want to order some sort of mass gnoll genocide because of a mother's worries.  I'd just like to feel safe in my own home.", completion = "Thank you, {name}.  I'll be throwing these in the fire.  We don't want those gnolls just sneaking in and stealing them back.", sourceObjectiveStatus = "unverified-source-field" }
quests[27013] = { id = 27013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Too Close for Comfort", description = "I'm happy for Nathaniel: he's spent so long trying to return to Northridge, and now with the Scarlet Crusade out of the way, he can finally move back home.  It's just... even for such a seemingly-idyllic setting, it's not really the best place to raise a family.\n\nFor example: along this valley's edge, you will find rabid foxes searching for innocent prey.  Every once in a while I catch a glimpse of one looking right at me.\n\nPlease, {class}, remove some of these foxes.  I don't feel safe with them near.", sourceObjective = "Kill 12 Rabid Foxes near Northridge Lumber Mill in Western Plaguelands.", completion = "I feel a bit more relieved, {name}.  Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27014] = { id = 27014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallowed Note", description = "Just a moment ago a messenger was looking for you, {name}. I believe she was sent by the priest trainer, Seer Ravenfeather. If this note is from the seer, I would go looking for her immediately.", sourceObjective = "Speak to Seer Ravenfeather in Camp Narache.", progress = "I am pleased to meet you, {name}.", completion = "You have arrived at last. During your training in Camp Narache, I will guide you in the ways of the {class}. You have much to learn and I look forward to counting you among my students.", sourceObjectiveStatus = "unverified-source-field" }
quests[27015] = { id = 27015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consecrated Note", description = "Just a moment ago a messenger was looking for you, {name}. I believe she was sent by the paladin trainer, Sunwalker Helaku. If this note is from the sunwalker, I recommend going to see him immediately.", sourceObjective = "Speak to Sunwalker Helaku in Camp Narache.", progress = "I am pleased to meet you, {name}.", completion = "We have much to cover. In time, the ways of the sunwalkers will be as plain and natural to you as the shaman's conversations with the elements.", sourceObjectiveStatus = "unverified-source-field" }
quests[27016] = { id = 27016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Joy of Boar Hunting", description = "Try to contain your excitement, {name}, for you are in the presence of the greatest boar hunter in Azeroth!\n\nTheir cunning intellect, rapid speed, ferocious strength, and resilient hide... yes, boars are the quarry of only the most masterful of hunters. Amateurs need not apply!\n\nWhy, I bet you've never even hunted such an exotic beast. I'll bet silver any day that you can't match my record of ten boars killed. Try the ones on the eastern shore of the loch... but don't hurt yourself now, rookie!", sourceObjective = "Kill 10 Mudbelly Boars.", completion = "You've killed ten already? H...hah! While you were out, I've broken my previous record! To ten... hundred! Yes, ten hundred boars!\n\nA bet is a bet, I suppose... here's your consolation prize, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[27017] = { id = 27017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memories from a Lost Past", description = "It's funny the things you remember.  I spent 16 hours a day working the fields, and every seventh day I'd head into bustling Andorhal to sell what I'd grown.  It was a tough life, but we did alright.\n\nBut I barely remember any of that.  When I think back to those days, I think about Gloria's smile, or Andrea waving from the window whenever I'd look up from the plow.\n\nThe farm's just a bit to the east, but I'm not sure I'm ready to go back, {name}.  I'd just like to make sure I hold on to these memories.", sourceObjective = "Travel to the farm house in Gahrron's Withering and gather any mementos you can find.", progress = "I wouldn't expect you to indulge the whims of a nostalgic old man, {name}.  Still, if you find yourself in the area...", completion = "This... Gloria used to read from this prayer book every night!  How had I forgotten?  She was so devout, {name}.\n\n\n\nOh...\n\nThis painting... my daughter, Andrea... she loved to... to paint...", sourceObjectiveStatus = "unverified-source-field" }
quests[27019] = { id = 27019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourge of the Downs", description = "Outstanding!  My name is Belnistrasz, and I thank you for rescuing me.  I had given myself up for dead... or worse, as a meal for these Scourge-infested vermin.\n\nListen... rather than just flee, I want to make a difference for all of our sakes.  Would you be up to helping me out to that end?  It's probably dangerous, but somebody needs to do it and I seriously doubt other adventurers will wander into this desolate place.", sourceObjective = "If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him.", progress = "I'm not one for politics; I care not if your affiliations are for either Horde or Alliance.  I am more interested in squelching direct and dire threats to all the races... and we have quite a large one in here.\n\nIf you're willing to be a true hero for all people, then hand me the oathstone I have given you as a sign of commitment.  I'm... not from around these parts; an oathstone is important to people of my kind as a bond of agreement.", completion = "Fantastic, I thought you looked to be the heroic type!  We've got our work cut out for us {name}, I'm not going to lie to you.  If we stay focused on the task at hand, we should be able to come out on top.", sourceObjectiveStatus = "unverified-source-field" }
quests[27020] = { id = 27020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First Lesson", description = "You have done well. As you continue along your path, you will grow, learning new techniques that you couldn't have imagined before.\n\nYour first lesson is the power of experience. Go, learn a new ability, and demonstrate it for me.", sourceObjective = "Reach level 3 to learn Charge. Locate a Training Dummy in Camp Narache and practice using Charge.", progress = "Have you mastered the charge?", completion = "You have done well, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27021] = { id = 27021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Path", description = "It is time for your first lesson, {name}. You have a long way to go to master the ways of the hunter, but as you complete more of your journey, you begin to take new steps on that path.\n\nGo, get more experience, and figure out a new ability. Then, use it on the training dummies here.", sourceObjective = "Reach level 3 to learn Steady Shot. Locate a Training Dummy in Camp Narache and practice using Steady Shot 5 times.", progress = "Have you mastered the charge?", completion = "You have done well, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27022] = { id = 27022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extinguishing the Idol", description = "Near the entrance is an idol that functions as a macabre oven for the Quilboar; they...they literally consume their abductees from the Barrens.  I can shut down the idol and render it useless, but I need your aid in doing so.  My plan: escort me to the idol.  Once we arrive, I'll commence the ritual.  I'll barely be able to communicate with you, let alone defend myself.  Protect me while I shut down the idol.\n\nAre you with me, {race}? Can I count on you to help me end their atrocities?", sourceObjective = "Protect Belnistrasz.", completion = "Belnistrasz's sudden departure has left behind a burning brazier.  As you stare in to the flame, the image of a great-winged red dragon fills your mind.  A more graveled version of Belnistrasz's voice speaks directly to you.\n\n\"Indeed mortals, you are the heroes I had hoped you would be.  Thanks to you the butchery these beasts were perpetrating is a thing of the past.  My faith in your kind has been once more renewed.  Take this as a reward befitting of a hero.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[27023] = { id = 27023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Way of the Sunwalkers", description = "It is always a pleasure to meet a fellow Sunwalker. We are not as numerous as some of the more ancient orders, but our ways are no less powerful and our members no less respected.\n\nAs you continue on your journey, you will grow closer to the light and gain abilities you couldn't have imagined.\n\nGo, get more experience, and return when you've learned a new ability. Demonstrate it to me.", sourceObjective = "Reach level 3 to learn Seal of Command. Locate a Training Dummy in Camp Narache, cast Seal of Command on yourself and hit the dummy.", progress = "Have you mastered the use of your first seal and judgement?", completion = "You have made me proud, {name}. You will make a fine Sunwalker. Return when you desire further training.", sourceObjectiveStatus = "unverified-source-field" }
quests[27024] = { id = 27024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Partners in Crime", description = "Although Amnennar is the primary threat here, he is far from the only. You need to slay his lieutenants as well if their hold on the Downs is to be released.\n\nGlutton guards the beginning of the Spiral of Thorns.\n\nMordesh stands atop The Bone Pile inciting the Scourge into a ravenous frenzy.\n\nTuten'kash resides underground. In order to bring him out, you must strike the gong in The Caller's Chamber three times.\n\nGood luck, brave hero.", sourceObjective = "Kill Glutton, Mordresh Fire Eye, and Tuten'kash.", completion = "Well done! Without their leaders, the Scourge will pose no significant threat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27025] = { id = 27025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thistle While You Work", description = "It's stabthistle season! Stabthistle seeds are responsible for up to 89% of seed-related injuries among hunters.\n\nYou'll find Stabthistle seeds mostly in the lower woodland just north of the lodge. They're commonly found at the base of trees, and they will stab and hurt you.\n\nI'd advise you to avoid them, but I actually need someone to help remove them for the sake of safety! Bring me back Stabthistle seeds so we can make sure others don't get hurt.", sourceObjective = "Collect 6 Stabthistle Seeds.", progress = "Handle them safely, now!", completion = "I've been informed there's a bear warning active for the woodlands as well! They love those stabthistle seeds.\n\nIt's a good thing you gathered those so they don't attract more bears!", sourceObjectiveStatus = "unverified-source-field" }
quests[27026] = { id = 27026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defcon: Bobcat", description = "Stop everything! It's come to my attention that there's been bobcat sightings near the lodge. Bobcats!\n\nNow mind you, I've never seen a bobcat, but they're surely dangerous. They're like mountain lions or something. I don't want anyone leaving until the area is secure!\n\nAnyone but you, that is. I'll pay you to help secure the area, {class}. But don't get your face ripped off.", sourceObjective = "Kill 8 Bobcats.", completion = "Okay, yes, I have already been informed that bobcats are much smaller than I was assuming. But that's still pretty dangerous for gnomes!\n\nYou've done a good thing for the safety of this lodge, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[27027] = { id = 27027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Strike", description = "I know you've been busy helping the braves protect Camp Narache from the bristlebacks. We're going to need all the hammers and all the luck we can get.\n\nAs your skills increase, so does your connection to the elements. This gives you access to new abilities.\n\nThe first of these that we learn is Primal Strike. It should help you fell your enemies faster. Learn it, and then try it out.", sourceObjective = "Reach level 3 to learn Primal Strike, and then locate a Training Dummy in Camp Narache and practice using Primal Strike 3 times.", completion = "Well done, {name}. I see you will have no trouble mastering our more advanced arts as you gain experience. Return to me when you need further training.", sourceObjectiveStatus = "unverified-source-field" }
quests[27028] = { id = 27028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hornet Hunting", description = "We're always looking for new game around here. Daryl may like his boars, but the rest of us prefer things more exotic.\n\nNow, I'd never say the Loch draining was a good thing, but it did have a silver lining. The swampy ground's brought in new prey: Hornets!\n\nGiant hornets, mind you. Not many hunters have tussled with massive bugs before. It's rather novel.\n\nIf you'd like to give it a try, I'll wager with you. Bring me back some of those nice glossy wings of theirs and I'll pay up.", sourceObjective = "Collect 6 Glassy Hornet Wings.", progress = "How go those wasps?", completion = "Lovely specimens you've got there! Here's my wager, lad.", sourceObjectiveStatus = "unverified-source-field" }
quests[27029] = { id = 27029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cure the Scourge", description = "Far more effective than killing swarm after swarm of Scourge is finding a method to prevent living creatures from ever being turned into them. I have an idea for a fine powder that, when inhaled, may stop the entire process.\n\nI need withered tusks off the unliving Quilboar here to make this powder. Bring me an ample amount, and we may be able to stop the Scourge's growth for good.", sourceObjective = "Collect 20 Withered Tusks.", progress = "Do you have the tusks?", completion = "I have faith that this substance will prevent many future headaches. Thank you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27030] = { id = 27030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foxtails By The Handful", description = "We've seen more foxes in the hills lately. Cunning creatures, they are. A good test of a hunter's skills, and a fine profit to boot!\n\nIt's their tails, <lad/lass>. Fine and fluffy, they're just as good hung on yer belt to ward off fleas as they are to line the gloves of some fancy noble.\n\nListen to me prattle on. I'm no goblin; the thrill's in the hunt! But if you bring me back some foxtails, I'll still gladly pay you for 'em. You'll find the foxes just north of the lodge in the lower woodlands.", sourceObjective = "Collect 7 Fluffy Fox Tails.", progress = "What've you got for me?", completion = "Ahh, you see? Goods of the finest quality. Good work gettin' these.", sourceObjectiveStatus = "unverified-source-field" }
quests[27031] = { id = 27031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wing Nut", description = "I'm through with gyrocopters. Sure, they work, but when has that ever been good enough for a real gnome? I want real flight, with WINGS!\n\nI've been studying birds for years now, trying to unlock the final secret to building a machine that flies just like them. That elegant soaring and swooping, the rush of wind over the wings, ahh.\n\nYou! You can help me. I need the finest flight feathers you can find. The golden eagles circling near the lodge would be a fine choice...", sourceObjective = "Collect 3 Pristine Flight Feathers from Golden Eagles.", progress = "Only the finest feathers will do!", completion = "Beautiful. you've got an eye for quality!\n\nGreat minds think alike! It's clear you've got an enthusiasm for flight and fowl, so maybe you can help me further...", sourceObjectiveStatus = "unverified-source-field" }
quests[27032] = { id = 27032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bird is the Word", description = "I've actually nearly perfected my dream machine: The Skystrider! The world's first flying Mechanostrider! But, well'\n\nWhen I was putting the finishing touches on it in my secret cavern lab, my other creations became, er, jealous. Giving mechanical birds a personality to begin with was probably a bad idea, but that's already done.\n\nI need the Supermechanical Robo-Widget from the original Skystrider if I want to rebuild it! Please, journey into the cave and retrieve it for me!", sourceObjective = "Find the Rusted Skystrider inside Ironwing Cavern.", completion = "<The Skystrider sits silent, its chance to fly gone. An obvious hatch on the front is marked \"SRW\".>", sourceObjectiveStatus = "unverified-source-field" }
quests[27033] = { id = 27033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skystrider's Heart", description = "Opening the hatch, you find an imposing looking mechanical device hooked to several wires, gears, and who knows what else.\n\nIt's easily detached. Time to bring it back to Bingles.", sourceObjective = "Return the Supermechanical Robo-Widget to Bingles Blastenheimer at the Farstrider Lodge.", completion = "Perfect! Now that I've perfected the wing balance and have all the parts I need, all we need is a pilot.", sourceObjectiveStatus = "unverified-source-field" }
quests[27034] = { id = 27034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He's That Age", description = "I'm not making the Skystrider for me, {name}. Not even for gnomekind. I want my son to be the one to fly it.\n\nI'm old, and my reflexes aren't what they used to be. But my boy Ando could be the best pilot Azeroth's ever seen, if he'd just get over his teenage moodiness!\n\nHe sits out by the loch, staring at the sky all day. Something's been bothering him, and yet he refuses to talk to his own father about it. I'm at a loss!\n\nPlease, {name}, could you go talk to him? Tell him I need him to pilot the Skystrider!", sourceObjective = "Speak to Ando Blastenheimer on the east side of the Loch.", completion = "I don't care about my father and his silly inventions! It's all just nonsense!", sourceObjectiveStatus = "unverified-source-field" }
quests[27035] = { id = 27035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standing Up", description = "Look at them. The Twilight's Hammer ruined this land!\n\nThat cult caused this Cataclysm, and broke the Stonewrought Dam, and drained the entire Loch. And now they wander around the ruins like it's their home!\n\nIf there was any justice in this world, someone would march into their camp and break that artifact of theirs in half. But I'm too weak to even try it.\n\nAnd nobody else is brave enough either! Not even you! You see? It's all so stupid...", sourceObjective = "Destroy the Twilight Landshaper at the center of the Twilight's Hammer Camp.", progress = "See what I mean? You don't even care either.", completion = "You did it? You did! You fought them and won!\n\nThere's hope after all...", sourceObjectiveStatus = "unverified-source-field" }
quests[27036] = { id = 27036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyrin's Revenge", description = "I don't suppose you'd be interested in a little payback for His Boldness? Daryl does have some skill, it pains me to say.\n\nA year ago, a large bear had been the target of the Farstrider Lodge, but none of the hunters had any luck with him. So, Daryl thought he'd try his hand against him. All he had to show for his effort was that ugly scar over his eye.\n\nKill the bear, and I'm sure even Daryl would be speechless for once.\n\nThe bear, Ol' Sooty, can be found around his lair in the cave to the north.", sourceObjective = "Kill Ol' Sooty and obtain his head.", progress = "Ah, {name}! Back so soon? No doubt you've been at the hunt again? Don't worry if you've had some setbacks, in the long run it will make you better!\n\n...You couldn't get much worse, anyway...", completion = "Er... what's this? A bear's head, by the looks of it.\n\n<He runs a finger along his scar unconsciously.>\n\nWell, that's quite an interesting kill you have yourself there. Couldn't be that bear from back then...\n\n<He trails off then starts to visibly shake.>\n\nOh, take that away take it away! Get that grisly thing out of here!", sourceObjectiveStatus = "unverified-source-field" }
quests[27037] = { id = 27037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyrin's Revenge", description = "Light! Don't bring things like that into the Lodge... it's unsanitary, unspeakable, un... un... unsanitary!\n\nJust get it out of here, will you? No one wants to see your bloody little trophy, really!", sourceObjective = "Bring Ol' Sooty's head to Vyrin Swiftwind at the Farstrider Lodge.", progress = "Great job, {name}! We really showed him! Here, give me the head and I'll take care of it.", completion = "Thanks for helping me out with my little plan, {name}. I've been itching for months to get back at that snooty, stuck-up boy, and I'd say we did a pretty good job! Here, have this, you've earned it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27038] = { id = 27038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Parts", description = "<The Sergeant turns his attention to you.>\n\nLook here, if you want to help speed things up around here, get Flintlocke off my back. A whole shipment of siege engine parts was misplaced and now it's scattered all up and down the dock.\n\nGather up the missing parts and get them to Flintlocke so he can finish construction. He's just across the road from me, waiting.", sourceObjective = "Gather up 5 Missing Parts from around the Stormwind Harbor.", progress = "Eh wot?\n\nMy parts. Where are they? You can't build a tank without parts!\n\nIf yeh did, it'd be small. An' mostly inner-fectual.", completion = "<Flintlocke greedily digs through the machine parts, tossing choice picks over his shoulder.>\n\nOh aye, 'ere's the stuff.\n\n<He sticks his head all the way into one of the crates.>\n\nBut where's me powder? Everything's here but for the powder. I need explosives, man!\n\nYou tell the King, no powder, no power. I need me some kersplosions or I ain't leavin' port.", sourceObjectiveStatus = "unverified-source-field" }
quests[27039] = { id = 27039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Intentions", description = "Do you know why Mortuus appends 'nub' to your name, {name}? Because he is an incompetent sycophant that has trouble seeing through his oversized helmet. 'NUB' is your classification. You are now part of the NEW UNDERCITY BATALLION.\n\nBut enough with the comedy! I sent Deathstalker Yorick on a shadow operation two days ago. Her goal was to get information on the Gilneas Liberation Front and return. Three days and no word from her.\n\nHead southwest to the Ivar Patch and look for Yorick, {name}.", sourceObjective = "Find Deathstalker Yorick at the Ivar Patch in Silverpine Forest.", completion = "Belmont gets a little nervous and sends some newbie to look for me? Listen, I've been staking out the old Ivar cottage from inside this outhouse for three days. Your presence threatens the whole damn operation!\n\nThere's no time to explain. We have to act now or this mission will be compromised.", sourceObjectiveStatus = "unverified-source-field" }
quests[27040] = { id = 27040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decryption Made Easy", description = "We don't have the tools to decipher these encrypted plans. The Twilight's Hammer do, though.\n\nWould you be a sweetie and take the plans back up there to run them through their one-time decryption engines?", sourceObjective = "Decrypt 6 plans.", sourceObjectiveStatus = "unverified-source-field" }
quests[27041] = { id = 27041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decryption Made Easy", description = "We don't have the tools to decipher these encrypted plans. The Twilight's Hammer do, though.\n\nWould you take the plans back up there and run them through their one-time decryption engines?", sourceObjective = "Decrypt 6 plans.", sourceObjectiveStatus = "unverified-source-field" }
quests[27042] = { id = 27042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight Fire and Water and Air with...", description = "Did ye hear the blatherin' idiot while ye were up there? That's none other than Haethen Kaul, their leader.\n\nThe man's gone daft with power. He's pullin' it straight from them bound elementals, makin' him nigh invincible.\n\nThe only thing I can think of to get ye into proper shape fer a fight with him is fer ye to first kill all o' them elementals, gettin' their wards. That should protect ye from Haethen's spells.\n\nWell, most o' them anyway.", sourceObjective = "Acquire the Fire, Water, and Air Wards, and then slay Haethen Kaul.", completion = "That's the ol' spirit! One less nasty in this world that the little ones will have ta worry about when they go ta sleep at night.\n\nNot ta mention that we won't have ta be worrying about him none no more neither!\n\nNow let's see here. I think we have somethin' in our crates that'll make a fittin' reward fer ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[27043] = { id = 27043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight Fire and Water and Air with...", description = "Did you hear the man going on with his incessant yelling while you were up there? That's Haethen Kaul, their leader.\n\nIt's a well known fact that he's gone insane from the power he's drawing from their bound elementals. Unfortunately, it makes him nigh invincible.\n\nIf you're to fight him, you'll first have to kill each of the elementals, gaining their wards in the process. That should protect you from Haethen's magic.\n\nWell, most of it anyway.", sourceObjective = "Acquire the Fire, Water, and Air Wards, and then slay Haethen Kaul.", completion = "An excellent display of {class} prowess.\n\n\n\nI believe that a reward is in order. Something appropriate for a powerful man such as yourself.", sourceObjectiveStatus = "unverified-source-field" }
quests[27044] = { id = 27044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peasant Problems", description = "I'm not quite ready to go back to the keep yet. Would you like to help me with something?\n\nRecently some of the local farmers were petitioning the King about some missing livestock. My father promised someone would investigate, but the city guard is stretched so thin it'll take weeks.\n\nI thought I would help! It'll encourage the farmers to see someone take action, especially from the royal family. Besides, it's just some missing cows. Nothing dangerous.\n\nTake me to Farmer Wollerton here in the city!", sourceObjective = "Escort Prince Anduin to Farmer Wollerton at the Wollerton Stead within Stormwind City. If he's no longer with you, you can find him in Stormwind Keep.", progress = "Uh, yup?", completion = "<On seeing the Prince Regent, Farmer Wollerton collapses awkwardly down on one knee.>\n\nY- Y- Your highness!", sourceObjectiveStatus = "unverified-source-field" }
quests[27045] = { id = 27045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waiting to Exsanguinate", description = "The Gilneas Liberation Front leader, Darius Crowley, has been meeting with another worgen inside this cottage for the past three days. I'm not sure what's going on, but we need to get inside the cottage and find a good hiding place from where we can eavesdrop.\n\nIt's now or never, {race}. We may never get another shot.\n\nJust promise me that if I don't make it, you'll return to Forsaken High Command and inform Belmont of whatever we discover.", sourceObjective = "Enter the Ivar Cottage and find a suitable hiding place upstairs. Then eavesdrop on Lord Darius Crowley.", completion = "Alas, poor Yorick! I knew her, {name}. An assassin of infinite courage...\n\nNow, tell me what's going on? What did you and Yorick discover?", sourceObjectiveStatus = "unverified-source-field" }
quests[27046] = { id = 27046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fear of Boring", description = "The gyreworms infest the rock, eating away at it until our home will one day collapse. For every one that is killed, twice as many burst forth to follow, but we must carry on the fight. They must be extinguished.\n\nGo to the Crumbling Depths and slaughter any worms that you can find.", sourceObjective = "Kill 10 gyreworms.", completion = "You wage a war that we cannot. Thank you for your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[27047] = { id = 27047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Motes", description = "Some of the rarest crystals form in the most dangerous places. In the Crumbling Depths, you will find painite formations - much better than the gold that your races cherish so much.\n\nAs a being of flesh and a being of small stature, you can enter the Crumbling Depths to retrieve motes of painite for me. Would you undergo that danger on my behalf?", sourceObjective = "Recover 10 Motes of Painite.", progress = "Painite is one of the most valuable materials to us, particularly due to our inability to reach most of the deposits on our own.", completion = "Well done, {race}. These will do well.", sourceObjectiveStatus = "unverified-source-field" }
quests[27048] = { id = 27048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Underground Economy", description = "Hey! I need some help gatherin' crystals. The elementals trade top dollar for these things... if you help me gather all the different kinds, I'll cut you in on the profits.\n\nUse these bombs to blow out chunks from the bigger formations.\n\nI've got a nasty habit of packin' the explosives a bit thick. Mind the kick.", sourceObjective = "Use Ricket's Tickers to gather 3 Deep Alabaster Crystals, 3 Deep Celestite Crystals, 3 Deep Amethyst Crystals, and 3 Deep Garget Crystals.", progress = "Boom?", completion = "Well played!\n\nI've got this pretty sweet deal going. A bunch of shmucks go up there to Therazane's Throne and give all kinds of gold to D'lom for who-knows-what kinda crap. He forks all that cash over to me for these crystals. I go home freakin' rich for a couple chunks of rock.\n\nDon't tell no one though. I don't want no competition springin' up.\n\nThink you can come back later to help me get another load of crystals out?", sourceObjectiveStatus = "unverified-source-field" }
quests[27049] = { id = 27049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soft Rock", description = "The corruption of the Crimson Expanse has not subsided. Destroy the Fungal Behemoths that shower their filth upon our realm. If they continue to rise, we will continue to destroy them.", sourceObjective = "Kill 8 Fungal Behemoths.", completion = "Once the growth starts, it is near impossible to stomp back into submission. Through persistence our realm will one day be cleansed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27050] = { id = 27050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungal Fury", description = "Something upon the Crimson Expanse continues to spur disgusting growths upon the rock. New fungi are rising, and they need to be crushed before they can spread.", sourceObjective = "Destroy 10 of the newly sprouted mushrooms in the Crimson Expanse.", completion = "You are proficient at stepping on things. You would make an excellent giant.", sourceObjectiveStatus = "unverified-source-field" }
quests[27051] = { id = 27051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through Persistence", description = "The troggs did not disperse after you killed Glop. His servants recovered the growth agent that was left behind and continue to sow the seeds of corruption across the Crimson Expanse.\n\nHunt them down and recover any of the remaining Verlock Miracle-Grow that you find. It must be disposed of.", sourceObjective = "Retrieve a Bag of Verlok Miracle-Grow from the Verloks upon the Crimson Expanse.", progress = "Have you done as I've asked of you? We must weed out whatever growth agent remains within their possession.", completion = "Thank you, {race}. We will weed the rest out of their possession in time.", sourceObjectiveStatus = "unverified-source-field" }
quests[27053] = { id = 27053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gahrron's Withering Cauldron", description = "My analysis is complete!  The blight that affects the animals here is no residual disease.  No, it is something new... and I think I know what it is.\n\nThe Cult of the Damned maintains a plague cauldron on a farm called Gahrron's Withering.\n\nThis farm is due southeast of us, close to where the Eastern Plaguelands begin.  I need a sample from this cauldron to verify my suspicions.\n\nEliminate the cauldron lord present there for its key.  You will then be able to access the cauldron and obtain my sample.", sourceObjective = "Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.", progress = "An access panel to the cauldron remains securely fastened.  In order to open it, you will need to find the key.", completion = "Cauldron Lord Soulwrath's key disintegrates as it touches the lock on the access panel at the base of the cauldron's platform.  A slight clanking noise is heard within, and the access panel swings open to reveal more viscous toxins within the cauldron's framework.\n\nThere is a small spigot that the bottle fits well enough under, allowing you to draw a sample for Field Agent Kaartish back at the Menders' Stead.", sourceObjectiveStatus = "unverified-source-field" }
quests[27054] = { id = 27054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Acts", description = "The Cult of the Damned maintains a small camp to the east, Malicia Outpost, which they use for field training outside of the Scholomance.  We may have allowed them to proceed unchecked with this training for too long.\n\nIf cultists are truly using this plague to inoculate the wildlife, then Malicia Outpost must be where the inoculation is occurring.\n\nInstructor Malicia runs the outpost.  Find her, slay her, and find out who she's taking orders from.", sourceObjective = "Kill Instructor Malicia and obtain her Cult Orders.", progress = "You take a look at the paperwork Malicia was carrying...", completion = "The orders in Malicia's possession incriminate Darkmaster Gandling of the Scholomance, but they also conceal another important bit of information.", sourceObjectiveStatus = "unverified-source-field" }
quests[27055] = { id = 27055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Students of Krastinov", description = "The Cult orders state that the plague from the cauldron at Gahrron's Withering is in fact being used for TWO purposes.  The first is the practice of spreading disease through the animals of the plaguelands, which you already knew about.\n\nThe remainder of the plague is being shipped to the Weeping Cave, a cavern north of Malicia's Outpost, for use in some dark experiments.  Students of the Scholomance are using this plague to re-animate the dead!\n\nCertainly they must be stopped.", sourceObjective = "Kill 2 Krastinovian Disciples, 2 Flesh-Cobbled Brutes, 2 Flesh-Cobbled Rippers, and 4 Unholy Corpuscles within the Weeping Cave in Western Plaguelands.", completion = "You have gone above and beyond, {name}.  Not only have we set back the Cult of the Damned in their crusade to re-plague the plaguelands, but you have uncovered another set of dire plans: they continue to re-animate the dead!\n\nYour name will definitely be mentioned when this information is presented to Highlord Fordring, {name}.  You have my thanks, and the blessing of the Argent Crusade.", sourceObjectiveStatus = "unverified-source-field" }
quests[27056] = { id = 27056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belmont's Report", description = "<Belmont hands you a sealed envelope.>\n\nDeliver this report to Lady Sylvanas Windrunner. It is my assessment of the situation in Silverpine based upon your and Yorick's field work.\n\nIf we do not stamp out the worgen insurgents, they will overrun us. The time to act is now!", sourceObjective = "Deliver Belmont's Report to Lady Sylvanas Windrunner at Forsaken High Command in Silverpine Forest.", progress = "Kneel before your queen, {name}.", completion = "Crowley... A gnat. An insect, waiting to be crushed beneath my boot heel.\n\nSo he thinks to rouse the feral worgen of Silverpine? We shall show him and his allies the might of the Forsaken!\n\nBut first we must clean up the mess made by the Warchief's fleet. Without their aid we may lose this war.", sourceObjectiveStatus = "unverified-source-field" }
quests[27057] = { id = 27057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Stead", description = "You carefully close the spigot in the control panel, watching the cauldron's putrid ichors drip into the empty bottle.\n\nWith the poison in hand, it is time to return to Field Agent Kaartish at the Menders' Stead.", sourceObjective = "Bring the Filled Gahrron's Withering Bottle to Field Agent Kaartish at the Menders' Stead in Western Plaguelands.", progress = "Gahrron's Withering houses a viciously potent plague cauldron.  Once we have a sample of the plague it spews forth, we will be able to determine whether the Cult of the Damned is truly responsible for continuing to poison the land.", completion = "Good work.  One moment please...\n\n<The draenei takes a moment to compare your sample with a sample he presumably had distilled earlier.>\n\nYes, this appears to be the same corruption that is affecting the wildlife.  With this knowledge, and with your combat expertise, we may have the power to stop this.", sourceObjectiveStatus = "unverified-source-field" }
quests[27058] = { id = 27058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrong Sequence", description = "The Twilight's Hammer must be stopped from using the Waygate. There's only one thing to do.\n\nPunch in the wrong activation sequence and destroy it.\n\nHmm, let's see. Yes, here's one that opens upon the explosive depths of the Firelands, the elemental plane of fire. That should do nicely.", sourceObjective = "Use the Waygate Controller to punch in the wrong activation sequence, thereby destroying the Waygate.", completion = "You did it! You found out what the Twilight's Hammer were up to and you stopped them dead in their tracks!\n\n<Mowi gets up on her tippy toes and gives you a kiss on the cheek.>\n\nNow I'm certain that I have something around here for you.\n\n<She begins rummaging around for your reward.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27059] = { id = 27059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrong Sequence", description = "The Twilight's Hammer must be stopped from using the Waygate. There's only one thing to do.\n\nPunch in the wrong activation sequence and destroy it.\n\nHmm, let's see. Yes, here's one that opens upon the explosive depths of the Firelands, the elemental plane of fire. That should do nicely.", sourceObjective = "Use the Waygate Controller to punch in the wrong activation sequence, thereby destroying the Waygate.", progress = "Is the Waygate still operational, {name}?", completion = "You did it! Excellent work, my boy. You found out what the Twilight's Hammer were up to and you stopped them dead in their tracks!\n\n<Examiner Rowe pats you on the back with his bony hand.>\n\nNow I'm certain that I have something around here for you.\n\n<He begins rummaging around for your reward.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27060] = { id = 27060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unholy Cow", description = "<Farmer Wollerton tries to pull himself together.>\n\nCows? You're asking about the missing livestock?\n\nI normally just let the cows graze north of the house here. Occasionally one gets spirited away. Leaves a trail of gore. Who would do such a thing?\n\nI'm afraid to follow that trail myself... something sick is happening in Stormwind!", sourceObjective = "While escorting Anduin Wrynn, follow the trail of gore from Farmer Wollerton's Stead to the crime scene. Keep Anduin alive. If he's not with you, he will be waiting in Stormwind Keep.", progress = "This doesn't sound like ordinary cattle rustlers. Something strange is happening here, right in the middle of my city.", completion = "That was a close one! I can't believe you stood your ground against so many at once.\n\nIt looks like this site was used for some kind of twisted Twilight's Hammer initiation ritual. They're definitely active in Stormwind. What's this?\n\n<Anduin finds a badge resting on the shrine.>\n\nThis badge shows a crossed axe and hammer. It looks old. If we keep poking around, we might figure out what it means...", sourceObjectiveStatus = "unverified-source-field" }
quests[27061] = { id = 27061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Overlook", description = "The dragon they're speaking of is Abyssion, {name}.  It's not going to be easy to get the fragment off of him.\n\nMeet with Mylra again.  She is operating nearby at the Twilight Overlook.\n\nShe will tell you what our next move will be.", sourceObjective = "Speak to Stormcaller Mylra at the Twilight Overlook in Deepholm.", completion = "So we're going to have to take on Abyssion to get the fragment?  This operation just got a whole lot more difficult all of a sudden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27062] = { id = 27062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looming Threat", description = "The Quilboar in Razorfen Downs seem to have allied with the Scourge. This is dark news for us, {class}. We have dire enough problems dealing with these Grimtotem, we won't be able to handle an attack by the Scourge. Venture into Razorfen Downs, east of here, and see if you can find anyone that may be able to help you stop them before they decide to attack here.", sourceObjective = "Find help in Razorfen Downs.", completion = "You seem an able warrior. Perhaps you can help me put an end to the terrible evil here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27063] = { id = 27063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looming Threat", description = "The Scourge are a direct affront to nature. They have managed to corrupt the Quilboar in Razorfen Downs and now threaten to spread further into Thousand Needles and eventually, I fear, west into Feralas. You must go there and do anything you can to confine them. Perhaps you can find someone in the area to help you? The winds whisper of a powerful presence in the area.", sourceObjective = "Find help in Razorfen Downs.", completion = "You seem an able warrior. Perhaps you can help me put an end to the terrible evil here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27064] = { id = 27064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He's Holding Out on Us", description = "{name}, it almost seems like Samuelson is trying to intentionally waste your time. The dockworkers don't know anything. More importantly, explosives are missing from Stormwind Harbor!\n\nYou know what I think? I bet Samuelson knows more than he's letting on. He probably has a lead on Twilight's Hammer and wants all the credit and glory for himself.\n\nWe should peek through his records at the SI:7 headquarters. Take me there and I should be allowed to look at his files and find out what he really knows.", sourceObjective = "Escort Anduin Wrynn to the third floor of SI:7 Headquarters in the Old Town district of Stormwind. If he is no longer with you, you can find Anduin in Stormwind Keep.", progress = "It's time we got some answers!", completion = "This is REALLY suspicious, {name}! Samuelson doesn't have a shred of info here about the Twilight Hammer - it's almost like he's not investigating them. Yet he's got a complete catalog of the missing explosives.\n\n\n\nAnd I found this funny badge with a symbol on it: A crossed axe and hammer.\n\nIt all means something, but what?", sourceObjectiveStatus = "unverified-source-field" }
quests[27065] = { id = 27065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warchief's Fleet", description = "Our reinforcements from Kalimdor arrived last night. Three orc gunships full of supplies, weapons and soldiers. Three orc gunships lost to Bloodfang's damned worgen.\n\nHow could an entire orc fleet lose to a small band of enemy combatants that lack any siege weaponry? An important question that you will answer for me.\n\nGather your gear and report to the orc admiral, Hatchet, at the Forsaken Rear Guard, southwest of here.\n\nGet those orcs operational, {name}.\n\nI await your full report.", sourceObjective = "Report to Admiral Hatchet at the Forsaken Rear Guard in Silverpine Forest.", completion = "This fiasco may go down as one of the biggest embarrassments in the history of naval warfare. How did this happen? Drunk happened. That's how.", sourceObjectiveStatus = "unverified-source-field" }
quests[27066] = { id = 27066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning the Word", description = "As you become more skilled, your skills will expand, and you will gain access to many new powers.\n\nGo - get some experience out there, and come back to me when you've learned something new. You can demonstrate on the training dummies nearby.", sourceObjective = "Reach level 3 to learn Shadow Word: Pain. Practice using it 5 times on Training Dummies in Camp Narache.", completion = "Thank you for your help in seeing to the wounded braves. I'm sure that you will often find your healing skills in demand. Return to me when you need further instruction.", sourceObjectiveStatus = "unverified-source-field" }
quests[27067] = { id = 27067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonfire", description = "As you develop your skills, druid, you will begin to feel your connection to the Earthmother deepening. You will begin to understand new secrets of nature, and learn to cast new spells.\n\nGo now, get more experience, and return to me when you've learned a new spell. Demonstrate what you've learned.", sourceObjective = "Reach level 3 to learn Moonfire. Practice using it on a Training Dummy in Camp Narache.", progress = "Have you seen to the injured of the wounded?", completion = "You have a knack for the druidic arts, {name}. Wherever you go, your skills will be in demand. Return to me when you are ready for more training.", sourceObjectiveStatus = "unverified-source-field" }
quests[27068] = { id = 27068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chief Ukorz Sandscalp", description = "Take a good look, mon. Dis is how it goes, betrayal after betrayal. I backstab you for the sword, and den Chief Ukorz go and backstab me even better for it.\n\nThat's life, yah! Or was...\n\nNow, I know you don't got no love for Mazoga. But I know you goin' in der anyway. Kill him for me, mon. Spill more blood on the sand, an' give Chief Ukorz Sandscalp what every one of de Sandfury deserves...a gory death.\n\nMaybe I leave some of my belongin's without a curse before passin' on if you do, yah?", sourceObjective = "Kill Chief Ukorz Sandscalp.", completion = "He's gone? Did he have the sword?\n\nNah...don't tell me. Don't matter no more. Mazoga don't care.\n\nI'm off now, mon. De consequences of my actions await me. Take whatever I was holdin'... I don't need it where I'm goin'...", sourceObjectiveStatus = "unverified-source-field" }
quests[27069] = { id = 27069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steel Thunder", description = "We may not have to live down the shame of this defeat, {name}. The Warchief will likely have us all executed instead.\n\nI'll be damned if we don't go down without a fight. Although the whole beachhead is overrun by Bloodfang worgen, there may still be hope. I want you to accompany one of our sea pups to the beachhead, directly west of here, and recover our supplies. Return to me when the pup can carry no more.", sourceObjective = "Recover 5 Sea Dog Crates.\n\nSpeak with Admiral Hatchet to get another Orc Sea Pup if you unexpectedly lose yours.", completion = "Within these crates are held STEEL THUNDER! With our weaponry returned we might have a chance to redeem ourselves.", sourceObjectiveStatus = "unverified-source-field" }
quests[27070] = { id = 27070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fool's Errand", description = "I heard that a troll in here, Hydromancer Velratha I think she was called, has come into the possession of a very rare, beautiful, and powerful piece of jewelry called the Tiara of the Deep. She uses it to control the powerful demigod Gahz'rilla, whose very scales are said to crackle with energy. Do you know what all of that means, {race}?\n\nI need it! Kill Velratha, take the Tiara of the Deep, and kill Gahz'rilla for one of his scales. Bring them all back to me pronto! I'll reward you handsomely.", sourceObjective = "Obtain the Tiara of the Deep and Gahzrilla's Electrified Scale.", progress = "Do you have what I need?", completion = "Excellent! This Tiara will grant me complete control of the water around here, and the Electrified Scale will serve to power all the machines I need to use it all to my advantage!\n\nYou're going to make me a very rich and powerful goblin! You can have this, it's nothing compared to what I'll have soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[27071] = { id = 27071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Sandfury", description = "De Sandfury are a resilient tribe. Dey have survived sandstorms an' years an' years of other tings long covered by da sands. It would be foolish to assume that the only forces here are da trolls. We been tamin' da scarabs, breedin' da sul'lithuz, an' raisin' our dead to keep on fightin' for all eternity as zombies.\n\nRuuzlu, da right hand of Chief Ukorz Sandscalp, be plannin' to use dem to retake Tanaris for de Sandfury empire. You best be killin' da trolls in charge of dis if you want to live, mon.", sourceObjective = "Kill Theka the Martyr, Witch Doctor Zum'rah, Antu'sul, and Ruuzlu.", completion = "You killed dem? All of dem? And you return alive?\n\nTake what you want off my body, den. It's mostly curse-free, Mazoga promises.", sourceObjectiveStatus = "unverified-source-field" }
quests[27072] = { id = 27072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Old Barracks", description = "I recognize the symbol on these badges from before Deathwing's attack on the city. It belonged to soldiers in the old barracks, west of town overlooking the harbor.\n\nYour timing couldn't be better. One of my top agents, Jack Bauden, has been trying to infiltrate the Twilight's Hammer cult for me. Last night he went missing. If you and Anduin are right, the cultists are holed up in the old barracks. Time is urgent! Assault the old barracks, take out those cultists, and rescue Jack Bauden.", sourceObjective = "Go to the Old Barracks and slay 6 Crazed Cultists, then locate Jack Bauden.", progress = "<Bauden is unconscious. This area still swarms with cultists! You'd better clear them out before investigating.>", completion = "<You slap Bauden around until he wakes up.>\n\n{class}? What are you doing here?\n\nI'm SI:7 Agent Jack Bauden. This is the longest day of my life.", sourceObjectiveStatus = "unverified-source-field" }
quests[27073] = { id = 27073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give 'em Hell!", description = "It's the goblins' fault, {race}!\n\n<hic!>\n\nYou see, we set off for Silverpine from Bilgewater Harbor, over in Azshara. Huge mistake that was! Never has such a den of inequity and sin existed in our great empire. Those damnable goblins fueled our every vice and set us off to sail with barrels full of ale. \n\n<hic!>\n\nThe shame of it all leaves a mark greater than any scar. Honor must be restored! Kill the Bloodfang worgen that ambushed us. They're scavenging the wreckage to the southwest.", sourceObjective = "Kill 10 Bloodfang Scavengers.", progress = "Give 'em hell, {race}!", completion = "Looks as if you really gave those worgen a beating and, in the process, lifted the \"shame haze\" they cast over us. Perhaps the sea dogs will quit drinkin' now.\n\nWho am I kidding?\n\nHah!", sourceObjectiveStatus = "unverified-source-field" }
quests[27074] = { id = 27074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight the Hammer", description = "You've done what I thought was impossible! I'm done moping around here. It's time to gnome up.\n\nI've got to find my father. But you! Don't bother yourself with me any longer. You've got to keep fighting these cultists.\n\nGo talk to Ashlan Stonesmirk to the east. He's trying to stop the Twilight's Hammer, but he has nobody to help him. You're his only hope!\n\nDon't give up, {name}. I won't.", sourceObjective = "Talk to Ashlan Stonesmirk near Mo'grosh Stronghold in Loch Modan.", completion = "You hit the twilight camp at the center of the lake? Not bad, lad!\n\nIf you're ready to take the fight right to their doorstep, I've got your chance.", sourceObjectiveStatus = "unverified-source-field" }
quests[27075] = { id = 27075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Servants of Cho'gall", description = "The Twilight's Hammer started as a clan of the savage Horde. Their leader, Cho'gall, slowly turned his band of ogres into a death cult, welcoming anyone insane enough to wish for the end of all existence. As you can see, there's still plenty of ogres among their ranks; deranged, fanatical, and just as strong as before.\n\nThese crude monsters have the gall to come here and spread their filth across our land. The more you kill, the better off Loch Modan will be, {name}.", sourceObjective = "Kill 7 Mo'grosh ogres in the Mo'grosh Stronghold.", completion = "It may look grim, but we'll win with your help, {name}. They won't keep the dwarves down.", sourceObjectiveStatus = "unverified-source-field" }
quests[27076] = { id = 27076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking and Entering", description = "A good buddy of mine, Weegli Blastfuse, joined up with Sergeant Bly and his group of outcasts to invade Zul'farrak and claim the legendary Sul'thraze as their prize. Of course, they underestimated the Sandfury tribe and now they're all trapped awaiting execution to please their demigod, Gahz'rilla!\n\nIf you free him, he'll help you blast your way to Ukorz's private chamber where he keeps at least part of the blade.\n\nKill his captors, Nekrum Gutchewer and Shadowpriest Sezz'ziz as revenge...I'll repay ya.", sourceObjective = "Free Weegli Blastfuse and kill Nekrum Gutchewer and Shadowpriest Sezz'ziz.", progress = "Are Nekrum and Sezz'ziz dead? If they are, I know Weegli will be here any minute now.", completion = "Wow! I knew I could count on you! Here's something for your troubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[27077] = { id = 27077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clutching at Chaos", description = "The cultists of the Twilight's Hammer use their powers to draw elementium metal from deep beneath the earth. They coax it out into twisted spikes to form their buildings, rooted right into the defiled ground.\n\nThe ogres here seem to be in the middle of weaving the stuff, and we need to strike while they're still twisting it into shape.\n\nTear the spikes right out of the ground while they're still pliable, and bring them back to me! We're not going to give these curs a single inch of our land.", sourceObjective = "Pull up 10 Nascent Elementium Spikes from the ground of the Mo'grosh Stronghold.", progress = "Did you tear up the spikes?", completion = "Shame that these half-formed things are too brittle and warped to be used for some weapons of our own. But it's thanks to you that we had the chance to get them out before they set. I'm not about to complain.", sourceObjectiveStatus = "unverified-source-field" }
quests[27078] = { id = 27078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gor'kresh", description = "The ogre left to watch over these crude fools goes by the name of Gor'kresh. He's big enough to boss even these brutes around, and cunning to boot. Never assume an ogre's stupid, that's when they'll get you.\n\nIf you take him out, we'll show the Twilight's Hammer that Loch Modan isn't a stepping stone for them. Stand strong against Gor'kresh and drive these fools back into the highlands!", sourceObjective = "Defeat Gor'kresh.", completion = "You've done it! We may not have stopped the cult dead, but we've shown them we're not easy pickings and given them a welt to prove it.\n\nTake this with my gratitude, and try not to blush if anyone in Thelsamar calls you \"hero\"!", sourceObjectiveStatus = "unverified-source-field" }
quests[27082] = { id = 27082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playing Dirty", description = "Have you seen the huge lumbering ettins roaming the forests? Cursed things came from Gilneas. Now they wander the land searching for their next juicy meal. We've managed to subjugate and utilize some of them to haul our wagons, but the others... well, they must be killed!\n\nUnfortunately, we can't spare any soldiers to do the job. That's where you come in, {class}!\n\nI have a plan, but it's going to require some materials. Head out into the forests around this base and collect diseased beast organs.", sourceObjective = "Collect 8 Diseased Organs from Giant Rabid Bears and Rabid Worgs.", progress = "We are Forsaken! This is how we do it, {class}.", completion = "Excellent! Now to prepare the \"meal.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[27083] = { id = 27083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Resumes!", description = "Word is in from Andorhal, {name}.  The battle has resumed.\n\nIt has become somewhat well-known among the Forsaken that you are a hero of the first battle of Andorhal.  Koltira has requested your presence immediately.", sourceObjective = "Report to Koltira Deathweaver at Andorhal in Western Plaguelands.", completion = "Thassarian and the humans made their move.  I thought I had an agreement with Thassarian... but I suppose this will do.", sourceObjectiveStatus = "unverified-source-field" }
quests[27084] = { id = 27084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Farmers' Militia", description = "The battle started when they attacked us from the rear.  I let my guard down, and a group of poorly-armed farmers and militiamen swung into our flank from the Writhing Haunt.\n\nThey may be weak, but unchecked, they threaten to overwhelm us with their numbers.\n\nLindsay's pet abominations can handle the melee combat.  You take this collar, stay in the rear, and use it to release my ebon gargoyle upon these farmers.", sourceObjective = "Use the Ebon Gargoyle Collar on 6 Provincial Militiamen within Andorhal.", completion = "Merely a dent in their numbers... but the sight of their fellow men falling from the skies surely weakened their resolve.", sourceObjectiveStatus = "unverified-source-field" }
quests[27085] = { id = 27085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supporting the Troops", description = "While it is true that these farmers threaten to overrun us, we still cannot forget about the Alliance's main forces.\n\nTravel west into Andorhal and slay the human soldiers that are fighting with our deathguards.  We need all the help we can get.", sourceObjective = "Slay 15 Andorhal Defenders.", completion = "You fight well, {name}.  I wish I had your ability... and your bravery.", sourceObjectiveStatus = "unverified-source-field" }
quests[27086] = { id = 27086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes to Ashes", description = "To the west, deep within Alliance-held Andorhal, you will find their commanders.  They do not fight, but call out orders from horseback.\n\nHunt down and slay these commanders, {name}.  The humans won't stand a chance.", sourceObjective = "Slay 3 Andorhal Force-Commanders.", completion = "Well done.  With them out of the way, I have no more excuses.\n\nSoon, I must battle Thassarian, for honor and for Andorhal.", sourceObjectiveStatus = "unverified-source-field" }
quests[27087] = { id = 27087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lindsay Ravensun, Revealed", description = "I was informed that that worthless woman, Lindsay Ravensun, would be here to support me in this battle, but so far, she's done nothing but brood within the basement of the greathall behind me.  All the better, I suppose.  She was a bit of a distraction.\n\nStill, I cannot and will not stand for insubordination.  Find her, and bring her to me.", sourceObjective = "Report to Lindsay Ravensun at Andorhal in Western Plaguelands.", completion = "You won't be taking me anywhere, {name}.\n\nWhile Koltira prances about with his playmate, Thassarian, I plan to win this battle.  Then I'll make Koltira suffer for his weakness.\n\nDon't believe me?  Fine, I'll let you in on a little secret...", sourceObjectiveStatus = "unverified-source-field" }
quests[27088] = { id = 27088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Only Poisonous if You Ingest It", description = "Take this cage, {class}. I've placed inside it one of my own mutant bush chickens, with a few slight modifications. Within the butt of this bush chicken is a stick of dynamite laced with gunk from the diseased organs you brought me.\n\nTake the cage out into the surrounding forest and locate the wandering forest ettin. Release the chicken and sit back as my masterwork does its job. The ensuing explosion should be sufficient to kill the ettin or greatly weaken it, allowing you to finish it off.", sourceObjective = "Use the Mutant Bush Chicken to kill the Forest Ettin.", completion = "<Apothecary Wormcrud laughs maniacally.>\n\nWas there ever any doubt? An ettin is no match for science!", sourceObjectiveStatus = "unverified-source-field" }
quests[27089] = { id = 27089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ace in the Hole", description = "You have no idea how difficult it was to stay disguised while I watched Koltira let this war slip away from us.  Even now, those infernal farmers threaten to overwhelm us.  All because he refused to slay a friend.\n\nTake my val'kyr again, {name}.  With her by your side, kill these farmers, convert them to Forsaken, and mobilize them.  Then take a group of them into Alliance-held western Andorhal and hunt down this death knight, Thassarian.\n\nWe will win this war yet.", sourceObjective = "With the Enthralled Val'kyr by your side, kill 5 Frightened Provincial Minutemen, then use your Call to Arms ability to turn them into Forsaken Troopers. Then find Thassarian in western Andorhal.", completion = "This is the body of Lurid, Thassarian's trusted knight.  With Thassarian nowhere to be found, it would seem that the Alliance forces have withdrawn.\n\nThe Forsaken have won the battle for Andorhal.", sourceObjectiveStatus = "unverified-source-field" }
quests[27090] = { id = 27090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andorhal, Once and For All", description = "Sylvanas will want to know about Thassarian's departure from Andorhal.  You resolve to return to the Forsaken-held side of town.", sourceObjective = "Report to Lady Sylvanas Windrunner at Andorhal in Western Plaguelands.", completion = "See?  All it took was a little help from the val'kyr.  These creatures are turning to be much more helpful than I had first thought.\n\nNow, on to other matters.", sourceObjectiveStatus = "unverified-source-field" }
quests[27091] = { id = 27091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charge!", description = "Good. You are off to a bright start. This road will be long, and as you become more accomplished, you will begin to discover that you can do things you could never have imagined before.\n\nGo, get more experience, and learn a new technique. Once you have, demonstrate it on one of the training dummies.", sourceObjective = "Reach level 3 to learn Charge. Locate a Training Dummy outside the Sunspire and practice using Charge.", progress = "Have you practiced your charge?", completion = "I think you've mastered the basics of the charge, {name}. Don't forget to return when you need more training.", sourceObjectiveStatus = "unverified-source-field" }
quests[27092] = { id = 27092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cataclysm in the Catacombs", description = "Don't worry about me, {class}. I've uncovered the Twilight's Hammer plot. They've been stealing and stockpiling explosives coming into Stormwind harbor. Somehow, they've gotten access to the catacombs underneath the Cathedral of Light. I've heard talk of someone called \"The Black Bishop.\"\n\nThere's no time to warn the guard, {name}! You've got just minutes to get into the catacombs and disarm that bomb. Go! Now! Or THOUSANDS of PEOPLE will DIE!", sourceObjective = "Enter the Cathedral of Light and descend into the catacombs below. Slay the Black Bishop and disarm the Pile of Explosives nearby.", progress = "<Dark magical runes cover the surface of the explosives, pulsing with increasing intensity...>\n\nYou've got to find the Black Bishop!", completion = "<3 ... 2 ... 1 ...>\n\n<You wet your fingers and snuff out the fuse. The cathedral is saved!>\n\n<Underneath the powder kegs you find a heap of notes and papers. Apparently the cultists were trying to destroy the evidence behind them.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27093] = { id = 27093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in the Darkness", description = "Some would say that we are lucky to be alive. Those people would be idiots. At least had we died we would not have had to face the Warchief's wrath. Alas, what's done is done! Now we must attempt to regain our lost honor.\n\nThe third ship in our fleet sank off the coast of the Skittering Dark, northwest of here. Those that made it to shore quickly found themselves swarmed by the giant spiders of the area and encased in webbing.\n\nIf there are survivors we must free them! Go, {name}! To the Skittering Dark!", sourceObjective = "Rescue 6 Orc Sea Dogs from the Skittering Dark.", completion = "Lok'tar, {name}! Once the ale wears off my orcs will be ready!", sourceObjectiveStatus = "unverified-source-field" }
quests[27094] = { id = 27094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deeper into Darkness", description = "The Skitterweb matriarch is nearby! You can put an end to the Skitterweb menace by killing her!\n\nFind the brood mother at the end of the cave in the Skittering Dark and destroy her!", sourceObjective = "Kill the Skitterweb Matriarch.", progress = "You killed the Skitterweb matriarch?", completion = "You rescued our orcs and killed the Skitterweb matriarch? We owe you a great debt of gratitude. You've saved us all from certain execution, {name}. I'm sure we can rouse these drunken idiots now.", sourceObjectiveStatus = "unverified-source-field" }
quests[27095] = { id = 27095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skitterweb Menace", description = "Vengeance is all consuming, {name}! Our third ship sank off the coast of the Skittering Dark, northwest of here. The men that made it off that boat were either captured or killed by the Skitterweb spiders of the region. For that, the spiders must die! ALL OF THEM!\n\nTravel to the Skittering Dark and crush those insects!\n\nBe on the lookout for their matriarch. Perhaps if we find her we can end this menace forever!", sourceObjective = "Kill 12 Skitterweb Spiders.", completion = "The root of this evil must be found and destroyed! The Skitterweb matriarch must be nearby. No doubt hiding in the nearby cave!", sourceObjectiveStatus = "unverified-source-field" }
quests[27096] = { id = 27096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orcs are in Order", description = "<Admiral Hatchet hands you an envelope sealed with the mark of the Horde.>\n\nThis is your commendation letter. It's the least I could do for you given the circumstances.\n\nReturn to Lady Sylvanas Windrunner with the letter and inform her of our status. Let her know that we will be ready to march on her command.\n\nGoodbye, {name}. You are an excellent soldier.\n\nNortheast, <lad/ma'am>. To Forsaken High Command!", sourceObjective = "Deliver the Admiral's Commendation Letter to Lady Sylvanas Windrunner at Forsaken High Command in Silverpine Forest.", progress = "And the orcs?", completion = "<Sylvanas raises an eyebrow.>\n\nSo the orcs are in order?\n\n<Sylvanas reads the commendation letter.>\n\nRecovered their supplies? Killed a dozen worgen? Toppled an ettin? Freed their soldiers and destroyed the Skitterweb matriarch?\n\nI say this rarely, {name}, but I am impressed. Perhaps your ability matches your aspirations. We shall see, for now you will be tested!", sourceObjectiveStatus = "unverified-source-field" }
quests[27097] = { id = 27097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Forsaken", description = "Fenris Isle stands defiantly at the heart of Lordamere Lake - a cruel memory of a time long since passed.\n\nThough no longer infested by gnoll vermin, a new threat has emerged.  Human refugees, driven from their holdings in Hillsbrad, have fled to Fenris Isle in hopes of escaping defeat at our hands. A critical error on their part.\n\nYou are to take Agatha with you to Fenris Isle and slaughter all humans. She will raise the fallen as Forsaken, bolstering our forces in the process.\n\nDo not fail me, {name}.", sourceObjective = "Raise 15 Forsaken by killing humans on Fenris Isle.", progress = "Victory!", completion = "I see everything, {name}. Through Agatha all is known to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[27098] = { id = 27098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lordaeron", description = "Ride with me to the Sepulcher, {name}. There are many things I wish to discuss with you. It is imperative that you understand the history of Lordaeron and the plight of the Forsaken.", sourceObjective = "Accompany Lady Sylvanas Windrunner to the Sepulcher in Silverpine Forest.", completion = "Do you now understand the importance of our mission here? Crowley and his Alliance dogs must be stopped!", sourceObjectiveStatus = "unverified-source-field" }
quests[27099] = { id = 27099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Escape", description = "You must strike at their leaders, {name}. You will find them holed up in the old keep. Battle your way inside and find the holdouts! Turn them for your queen!\n\nNone shall escape the mighty grasp of the Forsaken!", sourceObjective = "Find the Refugee Leadership inside Fenris Keep.", completion = "It would seem that Crowley is more formidable than I anticipated. Still, he is a man - flesh and bone - full of secrets. Secrets that I know all about...\n\nYou have served me well, {name}. I could use someone of your ability at the Sepulcher. I have a plan to deal with Crowley and his insurgents once and for all. Will you help?", sourceObjectiveStatus = "unverified-source-field" }
quests[27100] = { id = 27100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Research", description = "The book you found appears to detail some form of research carried out by a member of the Twilight's Hammer.\n\nIt deals with the oozes in some way, but there are multiple pages missing.\n\nPerhaps if you found additional notes you might be able to make sense of it.", sourceObjective = "Obtain 4 Twilight Research Notes from Mercurial Oozes in the Upper Silvermarsh.", progress = "<You scroll through the notes, trying to put them in order.>", completion = "The notes deal with High Cultist Maziel's research on the elemental properties of quicksilver.\n\nHis obsession with the subject borders on the insane.", sourceObjectiveStatus = "unverified-source-field" }
quests[27101] = { id = 27101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maziel's Revelation", description = "The notes continue Maziel's rambling research into the properties of quicksilver and mercurial oozes.\n\nHe appears to have made a major discovery.  He mentions hiding his journal in the Lower Silvermarsh to the southwest.", sourceObjective = "Find Maziel's Journal at the Lower Silvermarsh in Deepholm.", completion = "Maziel's journal appears to be undamaged by the mercury.", sourceObjectiveStatus = "unverified-source-field" }
quests[27102] = { id = 27102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maziel's Ascendancy", description = "Maziel's journal chronicles a ritual of ascendancy that would transfigure his body to one of pure quicksilver.\n\nThe ritual would take place in the cave near the Lower Silvermarsh, where Maziel would feed upon the mercurial oozes until achieving full strength.\n\nPerhaps it is not too late to put an end to his madness.", sourceObjective = "Slay Maziel inside the Silverlight Cave in Deepholm.", completion = "You've disposed of an enemy before he could grow more powerful.  By eliminating Maziel you've also ensured that his powers will not be used against the Earthen Ring.", sourceObjectiveStatus = "unverified-source-field" }
quests[27103] = { id = 27103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shards of the Felvine", description = "The satyr Alzzin the Wildshaper has exerted his corrupt dominion over this part of Eldre'Thalas.  The Fruit of Fertility, now corrupted as the Felvine, should be close to Alzzin. It may be the key to purify this ancient place.\n\nWhen the great satyr falls, capture whatever essence of the Felvine you can.  Seal it in this Reliquary of Purity, and bring it to me.\n\nGood luck, and Cenarius' speed.", sourceObjective = "Use the Reliquary of Purity to capture a Felvine Shard.", progress = "With the Sealed Reliquary of Purity in our possession, it will be possible not only to remove a corrupting threat from the world but also to study it under our judicious watch.  Perhaps we can even devise new means to combat the taint of corruption that ever threatens Azeroth.", completion = "You have done well, {class}, and for that I am forever in your debt.  Though the war is far from over, a great battle has been won against those who would bring about our doom.\n\nPlease - accept this gold as a token of my enduring gratitude.  If we ever cleanse Dire Maul, know that you will be welcomed here as a hero. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27104] = { id = 27104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alzzin the Wildshaper", description = "The monster responsible for the ruin you see before you is called Alzzin the Wildshaper. To reach him, however, you will need to also slay Zevrim Thornhoof, the satyr who currently holds the still noble ancient Old Ironbark in his grasp.\n\nOnce Ironbark is free, he will help you make an entrance into Alzzin's domain. Enter and slay him without mercy, for there is no other way.", sourceObjective = "Kill Zevrim Thornhoof and Alzzin the Wildshaper.", completion = "Ah, very well done indeed. You've made an old spirit very happy this day. You deserve proper thanks for the risks you've taken.", sourceObjectiveStatus = "unverified-source-field" }
quests[27105] = { id = 27105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unwelcome Guest", description = "You will find that Dire Maul is filled with many nature and arcane elementals. Somehow, a water elemental has found its way into this area. Please gather its essence and take it to me. I am curious as to how one of their kind got here, and what sort of agenda it may have against the natural elements of Eldre'Thalas.", sourceObjective = "Collect the Hydrospawn Essence.", progress = "Do you carry the essence, or did the task prove too difficult?", completion = "It is very troublesome that a water elemental was here, let alone one that powerful. Take this as my thanks for your efforts. I must examine this essence for any knowledge it may contain.", sourceObjectiveStatus = "unverified-source-field" }
quests[27106] = { id = 27106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Villain Unmasked", description = "<You find a complete list of all the Twilight's Hammer cultists in Stormwind.>\n\n<More importantly, you discover a letter from Major Samuelson to his compatriots outlining this entire scheme. The Prince was right: Samuelson is the real villain here, using his connections as commander of the city guard to disguise cult activity.>\n\n<It's time to return to Stormwind Keep and bring Samuelson to justice!>", sourceObjective = "Unmask and slay Major Samuelson in the Stormwind Keep Throne Room.", progress = "You have evidence incriminating Samuelson? Let's see what he has to say for himself!", completion = "Samuelson - corrupted by the Twilight's Hammer? This must have been going on for years. Right here in my very keep!\n\nI am grateful that you and my son were able to get to the bottom of this before my city was brought to harm. I've underestimated how much Anduin has grown - his command of the holy light just saved my life, if not the entire kingdom.\n\nAs for you - words alone can't do justice to your heroism this day. Thank you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27107] = { id = 27107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pusillin The Thief", description = "Me take quick nap earlier and stupid fast imp take book! Dagg'thol need book to follow orders and Master need book to conquer! Gah!\n\nYou {race} help me get book from imp, and I give you shiny something. Go, imp right there to da left! KILL!!!", sourceObjective = "Convince Pusillin to give up the Book of Incantations.", progress = "{race} has book?", completion = "Now you watch Master use book to kill stupid trees and stupid goat men! YAR!", sourceObjectiveStatus = "unverified-source-field" }
quests[27108] = { id = 27108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lethtendris's Web", description = "Blood Elf Lethtendris has web to catch magic here. She use for herself, but Master want to use for good of whole world! You help get web from stupid elf and not only will Dagg'thol reward you, you see how Master use it way better!", sourceObjective = "Obtain Lethtendris's Web.", progress = "{name}, you have stupid elf's web?", completion = "This web have lots of magic! Master will be very happy now!\n\nAnd you make Dagg'thol happy, {race}. Take this so you believe how happy you make Dagg'thol!", sourceObjectiveStatus = "unverified-source-field" }
quests[27109] = { id = 27109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warped Defender", description = "The Ironbark and Warpwood were once the mighty protectors of Eldre'Thalas. Look at how they have fallen! Ultimately, their fate lies at the hands of myself and my fellow Highborne. We were reckless with our power, {race}.\n\nBut you, you can right the wrongs here! Venture forth and put Tendris Warpwood to rest. He was the mightiest and last defender of this area, and deserves spiritual release. Be wary, for if you do not dispose of the Ironbark Protectors prior to engaging Tendris, he will call them to assist.", sourceObjective = "Kill Tendris Warpwood.", completion = "Your work here was noble. Fret not, for Tendris' soul was crying to be put to rest. He is thankful.", sourceObjectiveStatus = "unverified-source-field" }
quests[27110] = { id = 27110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Madness Within", description = "This madness must come to an end. The age of the immortals has long since passed. Destroy the guardians surrounding the five pylons to lower the force field. When this is done, destroy Immol'thar. With the Prince's power greatly reduced from the demon's demise, attack and end him as well. Lay the spirits of this city to rest, adventurer, and make the Prince pay for his wrongdoings.", sourceObjective = "You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.\n\nEnter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.\n\nReturn to the Shen'dralar Ancient in the courtyard should you complete this quest.", progress = "Be wary, adventurer. The Prince is... persuasive.", completion = "We thank you, hero.", sourceObjectiveStatus = "unverified-source-field" }
quests[27111] = { id = 27111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Treasure of the Shen'dralar", description = "In the library, Athenaeum, you will find an ancient chest hidden beneath the stairway. Take from it that which you desire.", sourceObjective = "Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!", completion = "You open the chest to find...", sourceObjectiveStatus = "unverified-source-field" }
quests[27112] = { id = 27112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cursed Remains", description = "There are remaining beings here that pose a direct threat to us ever reclaiming this sacred city. Magister Kalendris and Illyana Ravenoak are both extremely dangerous and need to be disposed of as quickly as possible.\n\nExercise caution, for with there being so few remaining feeding off of Immol'thar's energies, they are likely to be stronger than they first appear.", sourceObjective = "Kill Magister Kalendris and Illyana Ravenoak.", completion = "Your dedication will make this all that much easier.", sourceObjectiveStatus = "unverified-source-field" }
quests[27113] = { id = 27113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shen'dralar Ancient", description = "Some beings here have miraculously managed to remain free of the darkness that runs so rampant. On the second story of the Court of the Highborne rests a Shen'dralar Ancient. Seek it out, it may hold a wealth of wisdom, perhaps even the secret to freeing Eldre'Thalas.", sourceObjective = "Speak to the Shen'dralar Ancient.", completion = "Our meeting is no coincidence, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27114] = { id = 27114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordok Taste Test", sourceObjective = "You da big boss now, so you get free sample of my better brews!  These drinks boost you up AND give you good buzz!  These are da good ones, chief... you try and tell Kreeg yourself!", sourceObjectiveStatus = "unverified-source-field" }
quests[27115] = { id = 27115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ando's Call", description = "You've done great work here, {name}. While you were out, that young Ando fellow was here looking for you. Said something about a metal bird.\n\nYou might want to go back to the shores of the Loch and see what he wanted.", sourceObjective = "Talk to Ando Blastenheimer.", completion = "It's working! My father brought it!", sourceObjectiveStatus = "unverified-source-field" }
quests[27116] = { id = 27116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Winds of Loch Modan", description = "Father finished the Skystrider. It's amazing! Once we get the bugs worked out, I'm going to use it to fight for justice, just like you.\n\nI know you've got to move on, and help other people, being a hero and all, but how about a ride? I'm about to take the Skystrider on its first flight, and I'll be honored if you join me. I'll drop you off at Algaz Station.\n\nWhat do you say?", sourceObjective = "Ride the Skystrider to Algaz Station and then speak with Mountaineer Stormpike.", completion = "What in blazes WAS that? A flying mechanostrider?\n\nYou know what, I don't want to know. I'm just going to pretend that didn't happen, and we'll be all nice and businesslike.", sourceObjectiveStatus = "unverified-source-field" }
quests[27117] = { id = 27117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brute Strength", description = "Gandling has brought his lieutenant, the Ravenian, with him.  This lumbering brute is far more dangerous than any of the other Scourge you will find upon the battlefield... even the abominations.\n\nYou will find the Ravenian within a tower near the southern end of town.  I recommend caution before fighting him, {name}.  He will not be a pushover.", sourceObjective = "Kill the Ravenian within Andorhal.", completion = "Excellently done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27118] = { id = 27118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Broken Trap", sourceObjective = "A large, broken trap lies before you.  From the looks of it, the ogres have tried to repair the trap but to no avail.\n\nA hastily written note lies next to the trap, and strangely enough it details exactly how to repair it: just a few simple adjustments ought to do it.  Were the trap repaired, an ogre passing near it might get trapped, and could be avoided.\n\nClearly, it would seem fortuitous that very few ogres know how to read.\n\nClearly.", sourceObjectiveStatus = "unverified-source-field" }
quests[27119] = { id = 27119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordok Ogre Suit", description = "If you're going to fight the king of the Gordok then you're going to need to get by Captain Kromcrush.  Now, you can get by him by killing him, sure.  You might actually want to leave him alive.\n\nHow, you ask? I think I know! An ogre suit!\n\nI'll make you one if you bring me an Ogre Tannin from upstairs.  I'm not going anywhere like this...", sourceObjective = "Bring an Ogre Tannin to Knot Thimblejack.", progress = "Just get me that Ogre Tannin, and I'll whip you up an ogre suit that will fool Captain Kromcrush into thinking you're one of his men.", completion = "Yeah, this will do the trick.  Just a slip here, and tuck here... heh - this is going to work out just fine!  <A broad smile beams from the chained goblin's face.>\n\nHere you go, you're all set.  Remember- this isn't the most securely fashioned item in the world.  You'll have ten minutes of use before it falls apart, and then you're not going to fool anybody!  Try using it just before you approach him to make sure it lasts as long as you're going to need it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27120] = { id = 27120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordok Ogre Suit", progress = "Need another suit, do ya?  Well, I'm not going anywhere soon it seems - bring me another Ogre Tannin, and I'll make you another ogre suit.", completion = "Here ya go {name} - put this thing on, and you'll have ten minutes to do whatever.  Good luck!\n\nOh, and if you happen to find a key to get me out of here, BY ALL MEANS LET ME KNOW!!!" }
quests[27122] = { id = 27122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fired Up and Not So Good To Go.", description = "Leave it to the Dark Irons to work with Ragnaros' toadies and worse. You can bet that insane Twilight's Hammer cult is behind the lot of this!\n\nTime to end their attacks on Ironforge once and for all. Oh, and tell Commander Cragfist what's happened here when we return; I'll need to work on getting the city and its good people back in order.", sourceObjective = "Slay Grand Ambassador Flamelash and inform Commander Cragfist in Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[27123] = { id = 27123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deepholm, Realm of Earth", description = "I knew you'd heed our call, {name}.  When Deathwing was first defeated by the other dragon aspects, he retreated to Deepholm, the realm of earth.\n\nDeathwing's return to our world left a rift open between Azeroth and Deepholm.\n\nIf we don't mend the breach, this land will be torn asunder.\n\nWe're doing our best to contain the damage on this side of the rift.  Aggra will take you through the rift so you can help repair the damage from the other side.\n\nGet on her wyvern when you're ready.", sourceObjective = "Jump on Aggra's Wyvern and fly into the breach at the Maelstrom. Once you're on the other side, speak to Maruut Stonebinder.", completion = "You've arrived just in time, {name}.  All our resources are tied up keeping the rift stable.\n\nWe need someone like you to help us recover the fragments of the World Pillar.", sourceObjectiveStatus = "unverified-source-field" }
quests[27124] = { id = 27124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfinished Gordok Business", description = "Now you da king, so maybe you get prized Gordok artifact back from Guard Mol'dar!  Da king before you never listened, just like all da other kings since da old timey Gordok king!\n\nArtifact is called da Gauntlet of Gordok Might.  Old timey stories say only da one true king da Gordok can get it back.  You find it and it will become mighty gauntlet you wear forever!  Yar, I show you!", sourceObjective = "Speak to Guard Mol'dar in Dire Maul.", completion = "Wow... you ARE da true king! Old king never even ask about da gauntlet!\n\nLook - this mark on da gauntlet an old old OLD timey magic mark, older than da Gordok they say.  Well, I learn one thing as little ogre - how to make mark come to life and give power back to gauntlet!\n\nI do it for you, king!  Here, take da gauntlet and rule FOREVER!", sourceObjectiveStatus = "unverified-source-field" }
